        PendingDial = @(
            'runtime_unlock_tuna_dial_attempt_started',
            'runtime_unlock_tuna_dial_attempt_failed',
            'runtime_unlock_tuna_dial_offer_duplicate_ignored',
            'runtime_unlock_tuna_dial_successor_offer_held',
            'runtime_unlock_tuna_dial_successor_offer_replay_decided',
            'runtime_unlock_retry_dispatch_install_committed',
            'runtime_unlock_retry_dispatch_install_confirmed',
            'runtime_unlock_offer_authority_boundary_decided',
            'runtime_unlock_retry_dispatch_observed',
            'filetransfer_route_transition_prepared')
        PostGrantHold = @(
            'runtime_unlock_retry_dispatch_authority_granted',
            'runtime_unlock_retry_dispatch_held_by_active_negotiation',
            'runtime_unlock_retry_dispatch_observed',
            'runtime_unlock_retry_dispatch_contract_settled',
            'runtime_unlock_retry_dispatch_settlement_reported',
            'runtime_unlock_retry_dispatch_settlement_decided',
            'session_recovery_contract_listener_rearm_completed',
            'session_recovery_contract_retry_dispatched',
            'session_recovery_contract_retry_authority_offer_window_refreshed',
            'runtime_unlock_retry_dispatch_chain_closed',
            'runtime_unlock_retry_lifecycle_chain_closed')
    }
    $earlyPredicateEventSets = @{}
    $earlyPredicateLines = @{}
    foreach ($predicateName in $earlyPredicateEventNames.Keys) {
        $eventSet = [System.Collections.Generic.HashSet[string]]::new(
            [System.StringComparer]::OrdinalIgnoreCase)
        foreach ($eventName in $earlyPredicateEventNames[$predicateName]) { [void]$eventSet.Add($eventName) }
        $earlyPredicateEventSets[$predicateName] = $eventSet
        $earlyPredicateLines[$predicateName] = [System.Collections.Generic.List[string]]::new()
    }
    $earlyEvidenceLineVisitCount = 0L
    foreach ($line in $evidenceLines) {
        $earlyEvidenceLineVisitCount++
        $eventName = Get-TunaGuiLogLineFieldValue -Line $line -Name 'event'
        if ([string]::IsNullOrWhiteSpace($eventName)) { continue }
        $indexedLine = "$line; gui_evidence_sequence=$earlyEvidenceLineVisitCount"
        foreach ($predicateName in $earlyPredicateEventSets.Keys) {
            if ($earlyPredicateEventSets[$predicateName].Contains($eventName)) {
                $earlyPredicateLines[$predicateName].Add($indexedLine)
            }
        }
    }

    $responderPeerProbeFastPath =
        Get-TunaGuiRuntimeUnlockResponderPeerProbeHandoffFailure `
            -Lines ([string[]]$earlyPredicateLines.Responder.ToArray())
    $initialResponderDrainFastPath =
        Get-TunaGuiInitialResponderDrainReceiptFailure `
            -Lines ([string[]]$earlyPredicateLines.RouteDrain.ToArray())
    $fallbackFrontierCheckpointAcceptanceRecheckFastPath =
        Get-TunaGuiFallbackFrontierCheckpointAcceptanceRecheckFailure `
            -Lines ([string[]]$earlyPredicateLines.Checkpoint.ToArray())
    $currentListenerAdoptionFastPath =
        Get-TunaGuiCurrentListenerAdoptionFailure `
            -Lines ([string[]]$earlyPredicateLines.Adoption.ToArray())
    $fallbackTailRepairUnblockFastPath =
        Get-TunaGuiFallbackTailRepairUnblockRecheckFailure `
            -Lines ([string[]]$earlyPredicateLines.Unblock.ToArray())
    $installedRetryPendingDialFastPath =
        Test-TunaGuiInstalledRetryOfferPendingDuplicateNotReplayed `
            -Lines ([string[]]$earlyPredicateLines.PendingDial.ToArray())
    $postGrantHoldFastPath =
        Get-TunaGuiRuntimeUnlockRetryPostGrantHoldFailure `
            -Lines ([string[]]$earlyPredicateLines.PostGrantHold.ToArray())
    $installedRetryPendingDialFirstSequence = [long]::MaxValue
    if ($installedRetryPendingDialFastPath) {
        $firstPendingDialCandidate = @($earlyPredicateLines.PendingDial | Where-Object {
                (Get-TunaGuiLogLineFieldValue -Line $_ -Name 'event') -in @(
                    'runtime_unlock_tuna_dial_offer_duplicate_ignored',
                    'runtime_unlock_tuna_dial_successor_offer_held')
            } | Select-Object -First 1)
        if ($firstPendingDialCandidate.Count -eq 1) {
            $sequenceText = Get-TunaGuiLogLineFieldValue `
                -Line $firstPendingDialCandidate[0] `
                -Name 'gui_evidence_sequence'
            if ($sequenceText -match '^[1-9][0-9]*$') {
                $installedRetryPendingDialFirstSequence = [long]$sequenceText
            }
        }
    }
    $earlyRouteRuntimeFailures = @()
    foreach ($candidate in @(
            [pscustomobject]@{ Kind = 'RouteDrain'; Result = $initialResponderDrainFastPath },
            [pscustomobject]@{ Kind = 'Responder'; Result = $responderPeerProbeFastPath },
            [pscustomobject]@{ Kind = 'Checkpoint'; Result = $fallbackFrontierCheckpointAcceptanceRecheckFastPath },
            [pscustomobject]@{ Kind = 'Adoption'; Result = $currentListenerAdoptionFastPath },
            [pscustomobject]@{ Kind = 'Unblock'; Result = $fallbackTailRepairUnblockFastPath },
            [pscustomobject]@{ Kind = 'PostGrantHold'; Result = $postGrantHoldFastPath },
            [pscustomobject]@{
                Kind = 'PendingDial'
                Result = [pscustomobject]@{
                    Unresolved = [bool]$installedRetryPendingDialFastPath
                    FirstSequence = $installedRetryPendingDialFirstSequence
                }
            })) {
        if ([bool]$candidate.Result.Unresolved) {
            $earlyRouteRuntimeFailures += [pscustomobject]@{
                Kind = $candidate.Kind
                Sequence = [long]$candidate.Result.FirstSequence
            }
        }
    }
    $firstEarlyRouteRuntimeFailure = @($earlyRouteRuntimeFailures | Sort-Object Sequence | Select-Object -First 1)
    $firstEarlyRouteRuntimeKind = if ($firstEarlyRouteRuntimeFailure.Count -eq 1) {
        [string]$firstEarlyRouteRuntimeFailure[0].Kind
    }
    else { 'none' }

    if ($firstEarlyRouteRuntimeKind -eq 'RouteDrain') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource =
                "${classificationSource}_initial_responder_drain_receipt_index"
        }
        return New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_transition' `
            -Reason $initialResponderDrainFastPath.Reason `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_initial_responder_drain_receipt_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount ([long]$initialResponderDrainFastPath.ParsedRecords) `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
    }

    if ($firstEarlyRouteRuntimeKind -eq 'PostGrantHold') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource =
                "${classificationSource}_runtime_unlock_retry_post_grant_hold_index"
        }
        return New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'runtime_unlock_retry' `
            -Reason 'retry_dispatch_held_after_authority_granted' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_runtime_unlock_retry_post_grant_hold_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount ([long]$postGrantHoldFastPath.ParsedRecords) `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
    }

    if ($firstEarlyRouteRuntimeKind -eq 'PendingDial') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource =
                "${classificationSource}_installed_retry_pending_dial_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'runtime_unlock_initial_activation' `
            -Reason 'installed_retry_offer_pending_duplicate_not_replayed_after_other_dial_failure' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_installed_retry_pending_dial_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount ([long]$earlyPredicateLines.PendingDial.Count) `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.InitialActivationAnswerPeerDeliveryMissing = $true
        return $result
    }

    if ($firstEarlyRouteRuntimeKind -eq 'Responder') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = [long]$responderPeerProbeFastPath.LookupCount
            $TestMetrics.classificationSource = "${classificationSource}_responder_peer_probe_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason $(if ($responderPeerProbeFastPath.Variant -eq 'initial_activation_peer_acceptance_scope_rejected') {
                'initial_activation_zero_transport_epoch_peer_acceptance_scope_rejected_before_responder_convergence'
            } elseif ($responderPeerProbeFastPath.Variant -eq 'adoption_recheck_missing_after_answer_ack_before_probe') {
                'answer_ack_before_probe_acked_peer_probe_not_rechecked_into_responder_adopting_launch'
            } elseif ($responderPeerProbeFastPath.Variant -eq 'after_bound_handoff_missing') {
                if ($responderPeerProbeFastPath.FailureDecisionReason -ieq 'transfer_context_replaced') {
                    'bound_responder_acked_peer_probe_route_transition_handoff_invalidated_as_transfer_context_replaced'
                }
                else {
                    'bound_responder_acked_peer_probe_route_transition_handoff_invalidated'
                }
            } else {
                'late_answer_ack_did_not_bind_acked_peer_probe_to_responder_route_transition'
            }) `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_responder_peer_probe_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount ([long]$responderPeerProbeFastPath.ParsedRecords) `
            -EvidenceLookupCount ([long]$responderPeerProbeFastPath.LookupCount) `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.RuntimeUnlockResponderPeerProbeHandoffMissing = $true
        $result.RuntimeUnlockResponderPeerProbeInitialActivationPeerAcceptanceScopeRejected =
            [bool]$responderPeerProbeFastPath.InitialActivationPeerAcceptanceScopeRejected
        $result.RuntimeUnlockResponderPeerProbeBindingMissing = [bool]$responderPeerProbeFastPath.BindingMissing
        $result.RuntimeUnlockResponderPeerProbeAdoptionRecheckMissingAfterAnswerAckBeforeProbe =
            [bool]$responderPeerProbeFastPath.AdoptionRecheckMissingAfterAnswerAckBeforeProbe
        $result.RuntimeUnlockResponderPeerProbeRouteTransitionHandoffMissingAfterBoundProbe =
            [bool]$responderPeerProbeFastPath.AfterBoundHandoffMissing
        $result.FailureVariant = if (
            $responderPeerProbeFastPath.Variant -eq 'initial_activation_peer_acceptance_scope_rejected') {
            'runtime_unlock_responder_acked_probe_initial_activation_peer_acceptance_scope_rejected'
        }
        elseif (
            $responderPeerProbeFastPath.Variant -eq 'adoption_recheck_missing_after_answer_ack_before_probe') {
            'runtime_unlock_responder_acked_probe_adoption_recheck_missing_after_answer_ack_before_probe'
        }
        elseif ($responderPeerProbeFastPath.Variant -eq 'after_bound_handoff_missing') {
            'runtime_unlock_responder_acked_probe_route_transition_handoff_missing_after_bound_probe'
        }
        else {
            'runtime_unlock_responder_acked_probe_binding_missing'
        }
        return $result
    }

    if ($firstEarlyRouteRuntimeKind -eq 'Checkpoint') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_fallback_frontier_checkpoint_acceptance_recheck_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason 'checkpoint_pending_peer_frontier_request_not_rechecked_after_exact_checkpoint_acceptance' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_fallback_frontier_checkpoint_acceptance_recheck_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.FallbackFrontierCheckpointAcceptanceRecheckMissing = $true
        $result.CheckpointPendingFrontierRequestNotRecheckedAfterCheckpointAcceptance = $true
        return $result
    }

    if ($firstEarlyRouteRuntimeKind -eq 'Adoption') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_current_listener_adoption_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason 'live_coordinator_scoped_initial_activation_listener_reported_missing_for_fallback_paired_retry' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_current_listener_adoption_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.RuntimeUnlockRetryCurrentListenerAdoptionMissing = $true
        $result.RuntimeUnlockRetryCurrentListenerAdoptionLiveProjectionMissing = $true
        return $result
    }

    if ($firstEarlyRouteRuntimeKind -eq 'Unblock') {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_fallback_tail_repair_unblock_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason $fallbackTailRepairUnblockFastPath.Reason `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_fallback_tail_repair_unblock_index" `
            -EvidenceLineVisitCount $earlyEvidenceLineVisitCount `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.RuntimeUnlockRetryFallbackTailUnblockRecheckMissing = $true
        $result.RuntimeUnlockRetryFallbackFrontierRepairHoldBindingMissing =
            [bool]$fallbackTailRepairUnblockFastPath.HoldBindingMissing
        $result.RuntimeUnlockRetryFallbackFrontierRepairSettlementRecheckAfterBoundHoldMissing =
            [bool]$fallbackTailRepairUnblockFastPath.SettlementRecheckAfterBoundHoldMissing
        return $result
    }

    $fallbackPairedYieldRetrySourceScopeFastPath =
        Get-TunaGuiFallbackPairedYieldRetrySourceScopeFailure -Lines ([string[]]$evidenceLines)
    if ($fallbackPairedYieldRetrySourceScopeFastPath.Unresolved) {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = [long]$fallbackPairedYieldRetrySourceScopeFastPath.LineVisits
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_paired_yield_retry_source_scope_index"
        }
        return New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason 'fallback_paired_tail_yield_retry_request_source_scope_not_current' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_paired_yield_retry_source_scope_index" `
            -EvidenceLineVisitCount ([long]$fallbackPairedYieldRetrySourceScopeFastPath.LineVisits) `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
    }

    if ($null -ne $explicitResult) {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = $earlyEvidenceLineVisitCount
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = 'explicit_error'
        }
        $explicitResult.EvidenceLineVisitCount = $earlyEvidenceLineVisitCount
        $explicitResult.EvidenceParsedRecordCount = 0L
        $explicitResult.EvidenceLookupCount = 0L
        return $explicitResult
    }

    $fallbackTailPeerFirstFastPath =
        Get-TunaGuiFallbackTailPeerProofBeforeLocalYieldFailure -Lines ([string[]]$evidenceLines)
    if ($fallbackTailPeerFirstFastPath.Unresolved) {
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason $fallbackTailPeerFirstFastPath.Reason `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_fallback_tail_peer_first_index" `
            -EvidenceLineVisitCount ([long]$fallbackTailPeerFirstFastPath.LineVisits) `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.FallbackTailPeerProofBeforeLocalYieldNotRetained = $true
        $result.FallbackTailPeerProofBeforeLocalYieldAsymmetricRecoveryScopeNotRetained =
            $fallbackTailPeerFirstFastPath.Reason -eq
                'direction_local_recovery_generation_treated_as_shared_pair_scope'
        return $result
    }

    $fallbackTailFailedYieldFastPath =
        Get-TunaGuiFallbackTailFailedYieldQuiescentSuccessorFailure -Lines ([string[]]$evidenceLines)
    if ($fallbackTailFailedYieldFastPath.Unresolved) {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = [long]$fallbackTailFailedYieldFastPath.LineVisits
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_fallback_tail_failed_yield_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_runtime' `
            -Reason 'same_scope_failed_fallback_tail_yield_blocked_quiescent_successor' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_fallback_tail_failed_yield_index" `
            -EvidenceLineVisitCount ([long]$fallbackTailFailedYieldFastPath.LineVisits) `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.FallbackTailFailedYieldQuiescentSuccessorMissing = $true
        return $result
    }

    $retiredPendingAnswerFastPath =
        Get-TunaGuiRetiredPendingAnswerHandoffFailure -Lines ([string[]]$evidenceLines)
    if ($retiredPendingAnswerFastPath.Unresolved) {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = [long]$retiredPendingAnswerFastPath.LineVisits
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_retired_pending_answer_index"
        }
        $result = New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'runtime_unlock_initial_activation' `
            -Reason 'accepted_retired_pending_answer_not_promoted_to_runtime_unlock_transaction' `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_retired_pending_answer_index" `
            -EvidenceLineVisitCount ([long]$retiredPendingAnswerFastPath.LineVisits) `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
        $result.InitialActivationRetiredPendingAnswerHandoffMissing = $true
        return $result
    }

    $fallbackV6InvalidFrontierFastPath =
        Get-TunaGuiFallbackV6ProofBootstrapInvalidFrontierFailure -Lines ([string[]]$evidenceLines)
    if ($fallbackV6InvalidFrontierFastPath.Unresolved) {
        if ($null -ne $TestMetrics) {
            $TestMetrics.evidenceLineVisitCount = [long]$fallbackV6InvalidFrontierFastPath.LineVisits
            $TestMetrics.evidenceLookupCount = 0L
            $TestMetrics.classificationSource = "${classificationSource}_fallback_v6_bootstrap_index"
        }
        return New-TunaGuiFileTransferFailureClassificationResult `
            -Phase 'route_transition' `
            -Reason $fallbackV6InvalidFrontierFastPath.Reason `
            -RouteMode $RouteMode `
            -ClassificationSource "${classificationSource}_fallback_v6_bootstrap_index" `
            -EvidenceLineVisitCount ([long]$fallbackV6InvalidFrontierFastPath.LineVisits) `
            -EvidenceParsedRecordCount 0L `
            -EvidenceLookupCount 0L `
            -ClassificationElapsedMilliseconds $classificationStopwatch.ElapsedMilliseconds
    }

    function Test-TunaGuiLogLineHasEvent {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Line,
            [Parameter(Mandatory = $true)][string[]]$Events
        )

        foreach ($eventName in $Events) {
            if ($Line.IndexOf("event=$eventName", [System.StringComparison]::Ordinal) -ge 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiLogLineFieldMatch {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyString()][string]$SourceLine,
            [Parameter(Mandatory = $true)][AllowEmptyString()][string]$CandidateLine,
            [Parameter(Mandatory = $true)][string]$FieldName,
            [System.StringComparison]$Comparison = [System.StringComparison]::OrdinalIgnoreCase
        )

        $sourceValue = Get-TunaGuiLogLineFieldValue -Line $SourceLine -Name $FieldName
        $candidateValue = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $FieldName
        if ([string]::IsNullOrWhiteSpace($sourceValue) -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $sourceValue -eq '(none)' -or
            $candidateValue -eq '(none)') {
            return $true
        }

        return [string]::Equals($sourceValue, $candidateValue, $Comparison)
    }

    function Test-TunaGuiRuntimeUnlockFileTransferOwnerRejectionUnresolved {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines,
            [Parameter(Mandatory = $true)][string]$RejectionEvent
        )

        $indexedLines = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        $rejections = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @($RejectionEvent)
        })
        foreach ($rejection in $rejections) {
            $matchingAcceptance = @($indexedLines | Where-Object {
                $_.Index -gt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_filetransfer_owner_accepted_before_path_lease')) -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $rejection.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $rejection.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $rejection.Line -CandidateLine $_.Line -FieldName 'direction')
            })
            if ($matchingAcceptance.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiRuntimeUnlockMissingDispatchSuccessorUnresolved {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        $stableFields = @(
            'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
            'live_route_epoch', 'runtime_generation', 'terminal_generation', 'leg_generation',
            'route_publication_generation', 'route_commit_generation', 'contract_generation',
            'release_kind', 'release_authority_id', 'release_generation', 'release_outcome',
            'target_route', 'target_protocol_version', 'target_transport')
        $missingSettlements = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_dispatch_contract_settled')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_schema') -eq '2' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome') -eq 'MissingDispatch'
        })
        foreach ($settlement in $missingSettlements) {
            $predecessorId = Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'authority_id'
            $predecessorAttempt = [int](Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'dispatch_attempt_generation')
            $predecessorMissingDispatchGeneration = [int](Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'missing_dispatch_successor_generation')
            $failedOfferGeneration = [int64](Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'offer_generation')
            $successors = @($indexedLines | Where-Object {
                if ($_.Index -le $settlement.Index -or
                    -not (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_dispatch_authority_granted')) -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_schema') -ne '2' -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_authority_id') -ne $predecessorId -or
                    [int](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'dispatch_attempt_generation') -ne ($predecessorAttempt + 1) -or
                    [int](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'missing_dispatch_successor_generation') -ne ($predecessorMissingDispatchGeneration + 1) -or
                    ($failedOfferGeneration -gt 0 -and
                        [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retired_generation') -ne $failedOfferGeneration)) {
                    return $false
                }

                foreach ($fieldName in $stableFields) {
                    $predecessorValue = Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name $fieldName
                    $successorValue = Get-TunaGuiLogLineFieldValue -Line $_.Line -Name $fieldName
                    if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                        [string]::IsNullOrWhiteSpace($successorValue) -or
                        -not [string]::Equals(
                            $predecessorValue,
                            $successorValue,
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $false
                    }
                }
                return $true
            })
            if ($successors.Count -eq 1) {
                continue
            }

            $boundedRejection = @($indexedLines | Where-Object {
                if ($_.Index -le $settlement.Index -or
                    -not (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_successor_intent_rejected')) -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_schema') -ne '2' -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -ne $predecessorId -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_predecessor_authority_id') -ne $predecessorId -or
                    [int](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_dispatch_attempt_generation') -ne ($predecessorAttempt + 1) -or
                    [int](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_missing_dispatch_successor_generation') -ne ($predecessorMissingDispatchGeneration + 1) -or
                    ($failedOfferGeneration -gt 0 -and
                        [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_retired_generation') -ne $failedOfferGeneration)) {
                    return $false
                }

                foreach ($fieldName in $stableFields) {
                    $predecessorValue = Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name $fieldName
                    $rejectionValue = Get-TunaGuiLogLineFieldValue -Line $_.Line -Name $fieldName
                    if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                        [string]::IsNullOrWhiteSpace($rejectionValue) -or
                        -not [string]::Equals(
                            $predecessorValue,
                            $rejectionValue,
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $false
                    }
                }
                return $true
            })
            if ($boundedRejection.Count -gt 0) {
                continue
            }

            $settledPredecessorReuse = @($indexedLines | Where-Object {
                $_.Index -gt $settlement.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_dispatch_authority_rejected')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $predecessorId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'runtime_unlock_retry_authority_settled'
            })
            $terminal = @($indexedLines | Where-Object {
                $terminalEntry = $_
                $terminalLine = $terminalEntry.Line
                $terminalDirection = switch -Exact ((Get-TunaGuiLogLineFieldValue -Line $terminalLine -Name 'event')) {
                    'file_transfer_outbound_terminal' { 'outbound'; break }
                    'file_transfer_inbound_terminal' { 'inbound'; break }
                    'transfer_terminal' { Get-TunaGuiLogLineFieldValue -Line $terminalLine -Name 'direction'; break }
                    default { '' }
                }
                $terminalEntry.Index -gt $settlement.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $terminalLine -Events @('file_transfer_outbound_terminal', 'file_transfer_inbound_terminal', 'transfer_terminal')) -and
                (Get-TunaGuiLogLineFieldValue -Line $terminalLine -Name 'session_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'session_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $terminalLine -Name 'transfer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'transfer_id') -and
                $terminalDirection -eq
                    (Get-TunaGuiLogLineFieldValue -Line $settlement.Line -Name 'direction')
            })
            if ($settledPredecessorReuse.Count -gt 0 -or $terminal.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Get-TunaGuiRuntimeUnlockUnsettledGrantReason {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        $tupleFields = @(
            'authority_id', 'predecessor_authority_id', 'session_id', 'transfer_id', 'direction',
            'route', 'protocol_version', 'live_route_epoch', 'runtime_generation', 'terminal_generation',
            'leg_generation', 'transport_epoch', 'bridge_recovery_generation', 'bridge_decision_generation',
            'route_publication_generation', 'route_commit_generation', 'contract_generation',
            'retired_generation', 'dispatch_attempt_generation', 'missing_dispatch_successor_generation',
            'retry_reason', 'recovery_reason', 'release_kind', 'release_authority_id',
            'release_generation', 'release_outcome', 'target_route', 'target_protocol_version',
            'target_transport')
        $grants = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_dispatch_authority_granted')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_schema') -eq '2'
        })
        foreach ($grant in $grants) {
            foreach ($fieldName in $tupleFields) {
                if ([string]::IsNullOrWhiteSpace(
                        (Get-TunaGuiLogLineFieldValue -Line $grant.Line -Name $fieldName))) {
                    return 'runtime_unlock_retry_dispatch_contract_unsettled'
                }
            }

            $matchingSettlement = @($indexedLines | Where-Object {
                if ($_.Index -le $grant.Index -or
                    -not (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_retry_dispatch_contract_settled')) -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_schema') -ne '2') {
                    return $false
                }

                foreach ($fieldName in $tupleFields) {
                    $grantValue = Get-TunaGuiLogLineFieldValue -Line $grant.Line -Name $fieldName
                    $settlementValue = Get-TunaGuiLogLineFieldValue -Line $_.Line -Name $fieldName
                    if ([string]::IsNullOrWhiteSpace($grantValue) -or
                        [string]::IsNullOrWhiteSpace($settlementValue) -or
                        -not [string]::Equals(
                            $grantValue,
                            $settlementValue,
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $false
                    }
                }
                return $true
            })
            if ($matchingSettlement.Count -gt 0) {
                continue
            }

            $budgetSuppression = @($indexedLines | Where-Object {
                $_.Index -gt $grant.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_broken_state_retry_suppressed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $grant.Line -Name 'session_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $grant.Line -Name 'transfer_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'contract_generation') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $grant.Line -Name 'contract_generation')
            })
            return $(if ($budgetSuppression.Count -gt 0) {
                'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget'
            } else {
                'runtime_unlock_retry_dispatch_contract_unsettled'
            })
        }

        return '(none)'
    }

    function Test-TunaGuiRegularV4FrontierRepairMatch {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyString()][string]$SourceLine,
            [Parameter(Mandatory = $true)][AllowEmptyString()][string]$CandidateLine
        )

        $sourceKey = Get-TunaGuiLogLineFieldValue -Line $SourceLine -Name 'repair_request_key'
        $candidateKey = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name 'repair_request_key'
        if ([string]::IsNullOrWhiteSpace($sourceKey) -or
            [string]::IsNullOrWhiteSpace($candidateKey) -or
            -not [string]::Equals($sourceKey, $candidateKey, [System.StringComparison]::Ordinal)) {
            return $false
        }

        foreach ($fieldName in @(
                'transfer_id',
                'session_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'route_publication_generation')) {
            if (-not (Test-TunaGuiLogLineFieldMatch -SourceLine $SourceLine -CandidateLine $CandidateLine -FieldName $fieldName)) {
                return $false
            }
        }

        return $true
    }

    function Test-TunaGuiRegularV4FrontierRepairPrecontractClosureMatch {
        param(
            [Parameter(Mandatory = $true)]$Accepted,
            [Parameter(Mandatory = $true)]$Consumed,
            [Parameter(Mandatory = $true)]$Closure
        )

        if ($Consumed.Index -le $Accepted.Index -or $Closure.Index -le $Consumed.Index) {
            return $false
        }

        if (-not (Test-TunaGuiRegularV4FrontierRepairMatch -SourceLine $Accepted.Line -CandidateLine $Consumed.Line)) {
            return $false
        }

        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation')) {
            if (-not (Test-TunaGuiLogLineFieldMatch -SourceLine $Consumed.Line -CandidateLine $Closure.Line -FieldName $fieldName)) {
                return $false
            }
        }

        $consumedBridgeDecision = Get-TunaGuiLogLineFieldValue -Line $Consumed.Line -Name 'bridge_decision_generation'
        $closureBridgeDecision = Get-TunaGuiLogLineFieldValue -Line $Closure.Line -Name 'bridge_decision_generation'
        if (-not [string]::IsNullOrWhiteSpace($consumedBridgeDecision) -and
            -not [string]::IsNullOrWhiteSpace($closureBridgeDecision) -and
            $consumedBridgeDecision -ne '0' -and
            -not [string]::Equals($consumedBridgeDecision, $closureBridgeDecision, [System.StringComparison]::Ordinal)) {
            return $false
        }

        return $true
    }

    function Test-TunaGuiRetiredInitialActivationAnswerAuthorityTupleRejected {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexed = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        foreach ($rejection in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'runtime_unlock_offer_authority_boundary_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'boundary') -eq
                        'answer_received' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_mode') -eq
                        'InitialActivation' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                        'rejected' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq
                        'runtime_unlock_offer_authority_tuple_mismatch'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'session_id'
            $payer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'payer_decision_id'
            $offer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'offer_generation'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($payer) -or
                [string]::IsNullOrWhiteSpace($offer)) {
                continue
            }

            $preserved = @($indexed | Where-Object {
                $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_pending_runtime_unlock_answer_preserved',
                        'runtime_unlock_offer_peer_response_timeout_pending_answer_preserved')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'generation') -eq $offer
            } | Select-Object -Last 1)
            $slot = @($indexed | Where-Object {
                $preserved.Count -eq 1 -and
                $_.Index -gt $preserved[0].Index -and $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_retry_negotiation_slot_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @(
                    'Reserved', 'Converted') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -First 1)
            $install = @($indexed | Where-Object {
                $slot.Count -eq 1 -and
                $_.Index -gt $slot[0].Index -and $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_retry_dispatch_install_committed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_status') -eq
                    'Installed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -First 1)
            $confirmation = @($indexed | Where-Object {
                $install.Count -eq 1 -and
                $_.Index -gt $install[0].Index -and $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_retry_dispatch_install_confirmed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -First 1)
            $rawAnswer = @($indexed | Where-Object {
                $preserved.Count -eq 1 -and
                $_.Index -gt $preserved[0].Index -and $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_answer_received_raw')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -Last 1)
            if ($preserved.Count -ne 1 -or $slot.Count -ne 1 -or
                $install.Count -ne 1 -or $confirmation.Count -ne 1 -or
                $rawAnswer.Count -ne 1) {
                continue
            }

            $accepted = @($indexed | Where-Object {
                $_.Index -gt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_offer_authority_boundary_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'boundary') -eq
                    'answer_received' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @(
                    'accepted', 'idempotent') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'offer_generation') -eq $offer
            } | Select-Object -First 1)
            if ($accepted.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationAnswerPeerDeliveryMissing {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexed = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        $timeouts = @($indexed | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('tuna_acceleration_answer_ack_timeout')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'trigger') -eq 'runtime_unlock' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retry_reason') -eq
                'runtime_unlock_answer_ack_timeout'
        })
        foreach ($timeout in $timeouts) {
            $sessionId = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'session_id'
            $payerDecisionId = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'payer_decision_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'generation'
            $writer = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'log_writer_id'
            if ([string]::IsNullOrWhiteSpace($sessionId) -or
                [string]::IsNullOrWhiteSpace($payerDecisionId) -or
                [string]::IsNullOrWhiteSpace($generation) -or
                [string]::IsNullOrWhiteSpace($writer)) {
                continue
            }

            $pending = @($indexed | Where-Object {
                $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('tuna_acceleration_answer_ack_pending')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'generation') -eq $generation -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -Last 1)
            if ($pending.Count -ne 1) {
                continue
            }

            $sends = @($indexed | Where-Object {
                $_.Index -gt $pending[0].Index -and $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_answer_sent',
                        'tuna_acceleration_answer_replay_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            })
            if ($sends.Count -eq 0) {
                continue
            }

            $peerAnswer = @($indexed | Where-Object {
                $_.Index -gt $sends[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('tuna_acceleration_answer_received_raw')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -ne $writer
            } | Select-Object -First 1)
            $peerWriter = if ($peerAnswer.Count -eq 1) {
                Get-TunaGuiLogLineFieldValue -Line $peerAnswer[0].Line -Name 'log_writer_id'
            }
            else { '' }
            $ackTarget = @($indexed | Where-Object {
                $peerAnswer.Count -eq 1 -and
                $_.Index -gt $peerAnswer[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_acceleration_reply_target_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'purpose') -eq 'answer_ack' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'status') -eq 'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $peerWriter
            } | Select-Object -First 1)
            $localAck = @($indexed | Where-Object {
                $ackTarget.Count -eq 1 -and
                $_.Index -gt $peerAnswer[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_answer_ack_sent',
                        'tuna_acceleration_answer_ack_replay_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $peerWriter
            } | Select-Object -First 1)
            $responderReceipt = @($indexed | Where-Object {
                $localAck.Count -eq 1 -and
                $_.Index -gt $localAck[0].Index -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                ((Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'tuna_acceleration_answer_ack_received_raw',
                            'tuna_acceleration_answer_ack_received')) -or
                    ((Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'runtime_unlock_peer_precommit_answer_acceptance_decided')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'status') -in @(
                            'Accepted', 'Idempotent', 'accepted', 'idempotent')))
            } | Select-Object -First 1)
            $responderLaunch = @($indexed | Where-Object {
                $responderReceipt.Count -eq 1 -and
                $_.Index -gt $responderReceipt[0].Index -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_precommit_responder_peer_probe_handoff_bound',
                        'runtime_unlock_precommit_probe_launch_requested')) -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'launch_generation') -gt 0
            } | Select-Object -First 1)
            $inboundPrepared = @($indexed | Where-Object {
                $responderLaunch.Count -eq 1 -and
                $_.Index -gt $responderLaunch[0].Index -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'inbound' -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_route_transition_prepared'))
            } | Select-Object -First 1)
            if ($peerAnswer.Count -eq 0 -or
                $localAck.Count -eq 0 -or
                $ackTarget.Count -eq 0 -or
                $responderReceipt.Count -eq 0 -or
                $responderLaunch.Count -eq 0 -or
                $inboundPrepared.Count -eq 0) {
                return $true
            }
        }

        $failedDialDuplicates = @($indexed | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_tuna_dial_offer_duplicate_ignored')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                'runtime_unlock_tuna_dial_failed'
        })
        foreach ($duplicate in $failedDialDuplicates) {
            $sessionId = Get-TunaGuiLogLineFieldValue -Line $duplicate.Line -Name 'session_id'
            $payerDecisionId = Get-TunaGuiLogLineFieldValue -Line $duplicate.Line -Name 'payer_decision_id'
            $writer = Get-TunaGuiLogLineFieldValue -Line $duplicate.Line -Name 'log_writer_id'
            if ([string]::IsNullOrWhiteSpace($sessionId) -or
                [string]::IsNullOrWhiteSpace($payerDecisionId) -or
                [string]::IsNullOrWhiteSpace($writer)) {
                continue
            }

            $failure = @($indexed | Where-Object {
                $_.Index -lt $duplicate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_tuna_dial_attempt_failed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                    'runtime_unlock_tuna_dial_failed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -Last 1)
            $answer = @($indexed | Where-Object {
                $failure.Count -eq 1 -and
                $_.Index -gt $failure[0].Index -and $_.Index -lt $duplicate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('tuna_acceleration_answer_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'accepted') -eq '0' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'generation') -eq '0' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                    'runtime_unlock_tuna_dial_failed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -First 1)
            $target = @($indexed | Where-Object {
                $failure.Count -eq 1 -and $answer.Count -eq 1 -and
                $_.Index -gt $failure[0].Index -and $_.Index -le $answer[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_acceleration_reply_target_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'purpose') -eq 'answer' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'status') -eq 'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'target_mode') -eq
                    'validated_inbound_source' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -Last 1)
            $replay = @($indexed | Where-Object {
                $_.Index -gt $duplicate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_failed_dial_answer_replay_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer
            } | Select-Object -First 1)
            $peerReceipt = @($indexed | Where-Object {
                $answer.Count -eq 1 -and
                $_.Index -gt $answer[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_answer_received_raw')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -ne $writer
            } | Select-Object -First 1)
            if ($failure.Count -eq 1 -and
                $answer.Count -eq 1 -and
                $target.Count -eq 1 -and
                $replay.Count -eq 0 -and
                $peerReceipt.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationAnswerPeerRecoveryReplayWindowMissing {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexed = for ($index = 0; $index -lt $Lines.Count; $index++) {
            [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
        }
        foreach ($timeout in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'tuna_acceleration_answer_ack_timeout')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'trigger') -eq
                        'runtime_unlock'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'log_writer_id'
            $payer = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'payer_decision_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'generation'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($payer) -or
                [string]::IsNullOrWhiteSpace($generation)) {
                continue
            }

            $sends = @($indexed | Where-Object {
                $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'tuna_acceleration_answer_sent',
                        'tuna_acceleration_answer_replay_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payer
            })
            if ($sends.Count -eq 0) {
                continue
            }

            $lastSend = @($sends | Select-Object -Last 1)
            $target = @($indexed | Where-Object {
                $_.Index -le $lastSend[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_acceleration_reply_target_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq $payer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'generation') -eq $generation -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'status') -eq 'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'target_mode') -eq
                    'validated_inbound_source'
            } | Select-Object -Last 1)
            $peerReady = @($indexed | Where-Object {
                $_.Index -gt $lastSend[0].Index -and $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('bridge_ready')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -ne $writer
            } | Select-Object -First 1)
            $postReadyReplay = @($sends | Where-Object {
                $peerReady.Count -eq 1 -and $_.Index -gt $peerReady[0].Index
            }).Count -gt 0
            if ($target.Count -eq 1 -and $peerReady.Count -eq 1 -and -not $postReadyReplay) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationReceiveRecoveryHoldNotPreserved {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        function Get-InitialActivationField {
            param(
                [Parameter(Mandatory = $true)][string]$Line,
                [Parameter(Mandatory = $true)][string[]]$Names
            )

            foreach ($name in $Names) {
                $value = Get-TunaGuiLogLineFieldValue -Line $Line -Name $name
                if (-not [string]::IsNullOrWhiteSpace($value) -and
                    $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                    return $value
                }
            }
            return ''
        }

        function Test-InitialActivationWriterAndSession {
            param(
                [Parameter(Mandatory = $true)][string]$Left,
                [Parameter(Mandatory = $true)][string]$Right
            )

            foreach ($field in @('log_writer_id', 'session_id')) {
                $leftValue = Get-TunaGuiLogLineFieldValue -Line $Left -Name $field
                $rightValue = Get-TunaGuiLogLineFieldValue -Line $Right -Name $field
                if ([string]::IsNullOrWhiteSpace($leftValue) -or
                    [string]::IsNullOrWhiteSpace($rightValue) -or
                    -not [string]::Equals(
                        $leftValue,
                        $rightValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        function Test-InitialActivationWriter {
            param(
                [Parameter(Mandatory = $true)][string]$Left,
                [Parameter(Mandatory = $true)][string]$Right
            )

            $leftWriter = Get-TunaGuiLogLineFieldValue -Line $Left -Name 'log_writer_id'
            $rightWriter = Get-TunaGuiLogLineFieldValue -Line $Right -Name 'log_writer_id'
            return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
                -not [string]::IsNullOrWhiteSpace($rightWriter) -and
                [string]::Equals(
                    $leftWriter,
                    $rightWriter,
                    [System.StringComparison]::OrdinalIgnoreCase)
        }

        function Test-InitialActivationOfferTuple {
            param(
                [Parameter(Mandatory = $true)][string]$Boundary,
                [Parameter(Mandatory = $true)][string]$Candidate,
                [switch]$RequireTransaction
            )

            if (-not (Test-InitialActivationWriterAndSession -Left $Boundary -Right $Candidate)) {
                return $false
            }

            foreach ($mapping in @(
                    [pscustomobject]@{
                        Boundary = @('payer_decision_id')
                        Candidate = @('payer_decision_id')
                        Required = $true
                    },
                    [pscustomobject]@{
                        Boundary = @('offer_generation', 'generation')
                        Candidate = @('offer_generation', 'generation')
                        Required = $true
                    },
                    [pscustomobject]@{
                        Boundary = @('transaction_generation')
                        Candidate = @('transaction_generation')
                        Required = $RequireTransaction.IsPresent
                    },
                    [pscustomobject]@{
                        Boundary = @('tuna_path_lease_generation')
                        Candidate = @('tuna_path_lease_generation')
                        Required = $RequireTransaction.IsPresent
                    })) {
                $boundaryValue =
                    Get-InitialActivationField -Line $Boundary -Names $mapping.Boundary
                $candidateValue =
                    Get-InitialActivationField -Line $Candidate -Names $mapping.Candidate
                if (($mapping.Required -and
                        ([string]::IsNullOrWhiteSpace($boundaryValue) -or
                            [string]::IsNullOrWhiteSpace($candidateValue))) -or
                    (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                        -not [string]::Equals(
                            $boundaryValue,
                            $candidateValue,
                            [System.StringComparison]::OrdinalIgnoreCase))) {
                    return $false
                }
            }
            return $true
        }

        function Test-InitialActivationRecoveryOperationMatch {
            param(
                [Parameter(Mandatory = $true)][string]$Operation,
                [Parameter(Mandatory = $true)][string]$Candidate
            )

            foreach ($mapping in @(
                    [pscustomobject]@{
                        Operation = @('receive_recovery_operation_authority_id')
                        Candidate = @('receive_recovery_operation_authority_id')
                    },
                    [pscustomobject]@{
                        Operation = @('receive_recovery_operation_generation')
                        Candidate = @('receive_recovery_operation_generation')
                    },
                    [pscustomobject]@{
                        Operation = @('recovery_liveness_lease_authority_id')
                        Candidate = @('recovery_liveness_lease_authority_id')
                    },
                    [pscustomobject]@{
                        Operation = @('recovery_liveness_lease_generation')
                        Candidate = @('recovery_liveness_lease_generation')
                    },
                    [pscustomobject]@{
                        Operation = @('closure_generation', 'receive_recovery_closure_generation')
                        Candidate = @('closure_generation', 'receive_recovery_closure_generation')
                    })) {
                $operationValue =
                    Get-InitialActivationField -Line $Operation -Names $mapping.Operation
                $candidateValue =
                    Get-InitialActivationField -Line $Candidate -Names $mapping.Candidate
                if ([string]::IsNullOrWhiteSpace($operationValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue) -or
                    -not [string]::Equals(
                        $operationValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        function Test-InitialActivationHoldRequestMatch {
            param(
                [Parameter(Mandatory = $true)][string]$Left,
                [Parameter(Mandatory = $true)][string]$Right
            )

            foreach ($field in @(
                    'log_writer_id',
                    'session_id',
                    'transfer_id',
                    'direction',
                    'offer_nonce',
                    'payer_decision_id',
                    'offer_generation',
                    'transaction_generation',
                    'tuna_path_lease_generation',
                    'tuna_path_lease_listener_run_id',
                    'control_envelope_fingerprint')) {
                $leftValue = Get-TunaGuiLogLineFieldValue -Line $Left -Name $field
                $rightValue = Get-TunaGuiLogLineFieldValue -Line $Right -Name $field
                if ([string]::IsNullOrWhiteSpace($leftValue) -or
                    [string]::IsNullOrWhiteSpace($rightValue) -or
                    -not [string]::Equals(
                        $leftValue,
                        $rightValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $finalFailures = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'tuna_acceleration_activation_offer_not_observed')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_mode') -eq 'InitialActivation' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retry_scheduled') -eq '0' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retry_after_recovery_armed') -eq '0' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'pause_deferred') -eq '1' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'trigger') -in @(
                'runtime_unlock_offer_send_not_observed',
                'runtime_unlock_payer_intent_send_rejected')
        })

        foreach ($failure in $finalFailures) {
            $writerId = Get-TunaGuiLogLineFieldValue -Line $failure.Line -Name 'log_writer_id'
            $sessionId = Get-TunaGuiLogLineFieldValue -Line $failure.Line -Name 'session_id'
            $payerDecisionId =
                Get-TunaGuiLogLineFieldValue -Line $failure.Line -Name 'payer_decision_id'
            $offerGeneration =
                Get-TunaGuiLogLineFieldValue -Line $failure.Line -Name 'generation'
            if ([string]::IsNullOrWhiteSpace($writerId) -or
                [string]::IsNullOrWhiteSpace($sessionId) -or
                [string]::IsNullOrWhiteSpace($payerDecisionId) -or
                [string]::IsNullOrWhiteSpace($offerGeneration)) {
                continue
            }

            $boundary = @($indexedLines | Where-Object {
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_offer_authority_boundary_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_mode') -eq
                    'InitialActivation' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq
                    $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'offer_generation') -eq
                    $offerGeneration -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transaction_generation') -gt 0 -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'tuna_path_lease_generation') -gt 0
            } | Select-Object -Last 1)
            if ($boundary.Count -eq 0) {
                continue
            }

            $competingBoundaries = @($indexedLines | Where-Object {
                $_.Index -gt $boundary[0].Index -and
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_offer_authority_boundary_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_mode') -eq
                    'InitialActivation' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'accepted' -and
                (Test-InitialActivationWriter -Left $boundary[0].Line -Right $_.Line) -and
                -not (
                    (Test-InitialActivationWriterAndSession `
                        -Left $boundary[0].Line `
                        -Right $_.Line) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $boundary[0].Line `
                            -Name 'transfer_id') -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'transaction_generation') -eq
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $boundary[0].Line `
                            -Name 'transaction_generation')
                )
            })
            if ($competingBoundaries.Count -gt 0) {
                continue
            }

            $transferId =
                Get-TunaGuiLogLineFieldValue -Line $boundary[0].Line -Name 'transfer_id'
            $transactionGeneration =
                Get-TunaGuiLogLineFieldValue -Line $boundary[0].Line -Name 'transaction_generation'
            $candidateClosures = @($indexedLines | Where-Object {
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_closure_retained')) -and
                (Test-InitialActivationWriterAndSession `
                    -Left $boundary[0].Line `
                    -Right $_.Line) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transferId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_state') -eq 'Completed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq 'Completed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq 'Retained' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'proof_identity') -in @(
                    '', '(none)', 'none')
            } | Sort-Object Index -Descending)
            $closure = @()
            $deferrals = @()
            foreach ($candidateClosure in $candidateClosures) {
                $candidateDeferrals = @($indexedLines | Where-Object {
                    $deferral = $_
                    if ($deferral.Index -le $candidateClosure.Index -or
                        $deferral.Index -ge $failure.Index -or
                        -not (Test-TunaGuiLogLineHasEvent `
                            -Line $deferral.Line `
                            -Events @(
                                'tuna_activation_control_send_deferred_for_regular_v4_recovery')) -or
                        -not (Test-InitialActivationWriterAndSession `
                            -Left $boundary[0].Line `
                            -Right $deferral.Line) -or
                        (Get-TunaGuiLogLineFieldValue -Line $deferral.Line -Name 'purpose') -ne
                            'offer' -or
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $deferral.Line `
                            -Name 'blocker_reason') -ne
                            'receive_stall_recovery_awaiting_receive_proof') {
                        return $false
                    }

                    $latestClosure = @($indexedLines | Where-Object {
                        $_.Index -lt $deferral.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_receive_recovery_operation_closure_retained')) -and
                        (Test-InitialActivationWriterAndSession `
                            -Left $boundary[0].Line `
                            -Right $_.Line)
                    } | Select-Object -Last 1)
                    return $latestClosure.Count -eq 1 -and
                        (Test-InitialActivationRecoveryOperationMatch `
                            -Operation $candidateClosure.Line `
                            -Candidate $latestClosure[0].Line)
                })
                if ($candidateDeferrals.Count -ge 2) {
                    $closure = @($candidateClosure)
                    $deferrals = $candidateDeferrals
                    break
                }
            }
            if ($closure.Count -ne 1 -or $deferrals.Count -lt 2) {
                continue
            }

            $sameLineageBoundaries = @($indexedLines | Where-Object {
                $_.Index -ge $closure[0].Index -and
                $_.Index -le $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_offer_authority_boundary_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_mode') -eq
                    'InitialActivation' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transferId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transaction_generation') -eq
                    $transactionGeneration
            })
            $exhaustion = @($indexedLines | Where-Object {
                $_.Index -gt $boundary[0].Index -and
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'tuna_acceleration_retry_exhausted')) -and
                (Test-InitialActivationWriter -Left $boundary[0].Line -Right $_.Line) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                    'runtime_unlock_offer_send_not_observed'
            })
            if ($sameLineageBoundaries.Count -lt 2 -or $exhaustion.Count -ne 1) {
                continue
            }

            $heldDecisions = @($indexedLines | Where-Object {
                $_.Index -gt $closure[0].Index -and
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Held' -and
                (Test-InitialActivationOfferTuple `
                    -Boundary $boundary[0].Line `
                    -Candidate $_.Line `
                    -RequireTransaction) -and
                (Test-InitialActivationRecoveryOperationMatch `
                    -Operation $closure[0].Line `
                    -Candidate $_.Line)
            })
            $recovered = $false
            foreach ($held in $heldDecisions) {
                $adoptions = @($indexedLines | Where-Object {
                    $proof = $_
                    if ($proof.Index -le $held.Index -or
                        $proof.Index -ge $failure.Index -or
                        -not (Test-TunaGuiLogLineHasEvent -Line $proof.Line -Events @(
                            'filetransfer_receive_recovery_operation_proof_observed',
                            'filetransfer_receive_recovery_operation_closure_adopted')) -or
                        (Get-TunaGuiLogLineFieldValue -Line $proof.Line -Name 'closure_state') -ne
                            'Adopted' -or
                        -not (Test-InitialActivationWriterAndSession `
                            -Left $boundary[0].Line `
                            -Right $proof.Line)) {
                        return $false
                    }

                    if (Test-InitialActivationRecoveryOperationMatch `
                            -Operation $closure[0].Line `
                            -Candidate $proof.Line) {
                        return $true
                    }

                    $rebound = @($indexedLines | Where-Object {
                        $_.Index -gt $held.Index -and
                        $_.Index -lt $proof.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'runtime_unlock_initial_activation_receive_recovery_hold_rebound')) -and
                        (Test-InitialActivationOfferTuple `
                            -Boundary $boundary[0].Line `
                            -Candidate $_.Line `
                            -RequireTransaction) -and
                        (Get-InitialActivationField `
                            -Line $_.Line `
                            -Names @('previous_receive_recovery_operation_authority_id')) -eq
                            (Get-InitialActivationField `
                                -Line $closure[0].Line `
                                -Names @('receive_recovery_operation_authority_id')) -and
                        (Get-InitialActivationField `
                            -Line $_.Line `
                            -Names @('previous_receive_recovery_operation_generation')) -eq
                            (Get-InitialActivationField `
                                -Line $closure[0].Line `
                                -Names @('receive_recovery_operation_generation')) -and
                        (Test-InitialActivationRecoveryOperationMatch `
                            -Operation $proof.Line `
                            -Candidate $_.Line)
                    })
                    return $rebound.Count -gt 0
                })

                foreach ($adoption in $adoptions) {
                    $release = @($indexedLines | Where-Object {
                        $_.Index -gt $adoption.Index -and
                        $_.Index -lt $failure.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'runtime_unlock_initial_activation_receive_recovery_hold_decided',
                            'runtime_unlock_initial_activation_receive_recovery_hold_resumed')) -and
                        (
                            (Get-TunaGuiLogLineFieldValue `
                                -Line $_.Line `
                                -Name 'decision_status') -eq 'Released' -or
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'runtime_unlock_initial_activation_receive_recovery_hold_resumed'))
                        ) -and
                        (Test-InitialActivationHoldRequestMatch `
                            -Left $held.Line `
                            -Right $_.Line) -and
                        (Test-InitialActivationRecoveryOperationMatch `
                            -Operation $adoption.Line `
                            -Candidate $_.Line)
                    } | Select-Object -First 1)
                    if ($release.Count -eq 1) {
                        $recovered = $true
                        break
                    }
                }
                if ($recovered) {
                    break
                }
            }

            if (-not $recovered) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationReceiveRecoveryHoldReleasedOfferExpired {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        foreach ($rejection in @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'tuna_acceleration_message_rejected')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'message_type') -eq
                'transport_acceleration_offer' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq 'expired'
        })) {
            $peerWriter =
                Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'log_writer_id'
            $peerReceipt = @($indexedLines | Where-Object {
                $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'tuna_acceleration_offer_received_raw')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $peerWriter
            } | Select-Object -Last 1)
            if ($peerReceipt.Count -ne 1) {
                continue
            }

            $releases = @($indexedLines | Where-Object {
                $_.Index -lt $peerReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_resumed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'Released' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -ne
                    $peerWriter
            } | Select-Object -Last 1)
            if ($releases.Count -ne 1) {
                continue
            }
            $release = $releases[0]
            $sourceWriter =
                Get-TunaGuiLogLineFieldValue -Line $release.Line -Name 'log_writer_id'
            $sessionId =
                Get-TunaGuiLogLineFieldValue -Line $release.Line -Name 'session_id'
            $transferId =
                Get-TunaGuiLogLineFieldValue -Line $release.Line -Name 'transfer_id'
            $offerGeneration =
                Get-TunaGuiLogLineFieldValue -Line $release.Line -Name 'offer_generation'
            $payerDecisionId =
                Get-TunaGuiLogLineFieldValue -Line $release.Line -Name 'payer_decision_id'
            $envelopeFingerprint =
                Get-TunaGuiLogLineFieldValue `
                    -Line $release.Line `
                    -Name 'control_envelope_fingerprint'
            if ([string]::IsNullOrWhiteSpace($sourceWriter) -or
                [string]::IsNullOrWhiteSpace($sessionId) -or
                [string]::IsNullOrWhiteSpace($transferId) -or
                [string]::IsNullOrWhiteSpace($offerGeneration) -or
                [string]::IsNullOrWhiteSpace($payerDecisionId) -or
                [string]::IsNullOrWhiteSpace($envelopeFingerprint)) {
                continue
            }

            $held = @($indexedLines | Where-Object {
                $_.Index -lt $release.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'Held' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $sourceWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transferId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'offer_generation') -eq
                    $offerGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq
                    $payerDecisionId -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'control_envelope_fingerprint') -eq $envelopeFingerprint
            } | Select-Object -Last 1)
            $prevalidated = @($indexedLines | Where-Object {
                $_.Index -ge $release.Index -and
                $_.Index -lt $peerReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'Released' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $sourceWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'offer_generation') -eq
                    $offerGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'payer_decision_id') -eq
                    $payerDecisionId
            } | Select-Object -First 1)
            if ($held.Count -eq 1 -and $prevalidated.Count -eq 1) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationCommittedRefreshPrevalidationRejected {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        foreach ($candidate in @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'prevalidation_status') -eq
                'rejected' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                'Released' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'same_generation_resume') -eq
                '1'
        })) {
            $writer =
                Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'log_writer_id'
            $session =
                Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'session_id'
            $transfer =
                Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'transfer_id'
            $offerGeneration =
                Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'offer_generation'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                [string]::IsNullOrWhiteSpace($offerGeneration)) {
                continue
            }

            $commits = @($indexedLines | Where-Object {
                $_.Index -lt $candidate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_offer_envelope_refresh_committed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in
                    @('Accepted', 'Idempotent') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'offer_generation') -eq
                    $offerGeneration -and
                -not [string]::IsNullOrWhiteSpace(
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'refresh_generation'))
            } | Select-Object -Last 1)
            if ($commits.Count -ne 1) {
                continue
            }

            $refreshGeneration =
                Get-TunaGuiLogLineFieldValue `
                    -Line $commits[0].Line `
                    -Name 'refresh_generation'
            $released = @($indexedLines | Where-Object {
                $_.Index -gt $commits[0].Index -and
                $_.Index -lt $candidate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_directive_delivery_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq
                    'Released' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'refresh_generation') -eq
                    $refreshGeneration
            } | Select-Object -Last 1)
            $submitted = @($indexedLines | Where-Object {
                $_.Index -gt $candidate.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_post_prevalidation_submission')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'refresh_generation') -eq
                    $refreshGeneration
            })
            if ($released.Count -eq 1 -and $submitted.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiReceiveRecoveryCompletedProvenSuccessorMissing {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )

        function Test-TunaGuiCompletedProvenMeaningful {
            param([AllowNull()][AllowEmptyString()][string]$Value)

            return -not [string]::IsNullOrWhiteSpace($Value) -and
                $Value -notin @('(none)', 'none', '(missing)', '__missing__', '0')
        }

        function Test-TunaGuiCompletedProvenOperationMatch {
            param(
                [Parameter(Mandatory = $true)][string]$AnchorLine,
                [Parameter(Mandatory = $true)][string]$CandidateLine
            )

            foreach ($field in @(
                    'receive_recovery_operation_authority_id',
                    'receive_recovery_operation_generation',
                    'session_id',
                    'transfer_id',
                    'direction',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'bridge_decision_generation',
                    'data_session_generation',
                    'recovery_liveness_lease_authority_id',
                    'recovery_liveness_lease_generation')) {
                $anchor = Get-TunaGuiLogLineFieldValue -Line $AnchorLine -Name $field
                $candidate = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $field
                if ([string]::IsNullOrWhiteSpace($anchor) -or
                    [string]::IsNullOrWhiteSpace($candidate) -or
                    $anchor -eq '(none)' -or
                    $candidate -eq '(none)' -or
                    $anchor -ne $candidate) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiCompletedProvenConflictScope {
            param(
                [Parameter(Mandatory = $true)][string]$OperationLine,
                [Parameter(Mandatory = $true)][string]$ConflictLine
            )

            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                if (-not (Test-TunaGuiLogLineFieldMatch `
                        -SourceLine $OperationLine `
                        -CandidateLine $ConflictLine `
                        -FieldName $field)) {
                    return $false
                }
            }
            foreach ($pair in @(
                    @('route', 'current_route'),
                    @('protocol_version', 'current_protocol_version'),
                    @('live_route_epoch', 'current_live_route_epoch'),
                    @('runtime_generation', 'current_runtime_generation'),
                    @('terminal_generation', 'current_terminal_generation'),
                    @('leg_generation', 'attempted_leg_generation'),
                    @('transport_epoch', 'attempted_transport_epoch'),
                    @('bridge_recovery_generation', 'attempted_bridge_recovery_generation'))) {
                $expected = Get-TunaGuiLogLineFieldValue -Line $OperationLine -Name $pair[0]
                $actual = Get-TunaGuiLogLineFieldValue -Line $ConflictLine -Name $pair[1]
                if ([string]::IsNullOrWhiteSpace($expected) -or
                    [string]::IsNullOrWhiteSpace($actual) -or
                    $expected -eq '(none)' -or
                    $actual -eq '(none)' -or
                    $expected -ne $actual) {
                    return $false
                }
            }
            return $true
        }

        $issuedOperations = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'filetransfer_receive_recovery_operation_issued')
        })
        foreach ($issued in $issuedOperations) {
            $operationAuthority = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'receive_recovery_operation_authority_id'
            $operationGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'receive_recovery_operation_generation'
            if (-not (Test-TunaGuiCompletedProvenMeaningful $operationAuthority) -or
                -not (Test-TunaGuiCompletedProvenMeaningful $operationGeneration)) {
                continue
            }

            $started = @($indexedLines | Where-Object {
                $_.Index -gt $issued.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_started',
                    'filetransfer_receive_recovery_operation_execution_start_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_start_status') -in
                    @('Started', 'Idempotent') -and
                (Test-TunaGuiCompletedProvenOperationMatch `
                    -AnchorLine $issued.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($started.Count -eq 0) {
                continue
            }

            $receipt = @($indexedLines | Where-Object {
                $_.Index -gt $started[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq 'Completed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_state') -eq 'Completed' -and
                (Test-TunaGuiCompletedProvenOperationMatch `
                    -AnchorLine $issued.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            $proof = @($indexedLines | Where-Object {
                $_.Index -gt $issued.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_proof_observed')) -and
                (Test-TunaGuiCompletedProvenMeaningful (
                    Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'proof_identity')) -and
                (Test-TunaGuiCompletedProvenOperationMatch `
                    -AnchorLine $issued.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($receipt.Count -eq 0 -or $proof.Count -eq 0) {
                continue
            }

            $proofBoundary = [Math]::Max([int]$receipt[0].Index, [int]$proof[0].Index)
            $adopted = @($indexedLines | Where-Object {
                $_.Index -gt $proofBoundary -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_closure_adopted')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq 'Adopted' -and
                (Test-TunaGuiCompletedProvenOperationMatch `
                    -AnchorLine $issued.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($adopted.Count -eq 0) {
                continue
            }

            $conflicts = @($indexedLines | Where-Object {
                $_.Index -gt $adopted[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_recovery_authority_rejected')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'action_kind') -eq
                    'ReceiveRecoveryOperation' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'rejection_reason') -eq
                    'filetransfer_receive_recovery_operation_conflict' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'attempted_action') -in @(
                    'all_channels_zero_receive',
                    'receive_stall',
                    'ping_timeout',
                    'session_liveness_timeout_pending') -and
                (Test-TunaGuiCompletedProvenConflictScope `
                    -OperationLine $issued.Line `
                    -ConflictLine $_.Line)
            })
            foreach ($conflict in $conflicts) {
                $ownedBeforeConflict = @($indexedLines | Where-Object {
                    $_.Index -gt $adopted[0].Index -and
                    $_.Index -lt $conflict.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_closure_reserved',
                        'filetransfer_receive_recovery_operation_closure_consumed',
                        'filetransfer_receive_recovery_operation_invalidated',
                        'filetransfer_receive_recovery_operation_superseded')) -and
                    (Test-TunaGuiCompletedProvenOperationMatch `
                        -AnchorLine $issued.Line `
                        -CandidateLine $_.Line)
                })
                if ($ownedBeforeConflict.Count -gt 0) {
                    continue
                }

                $typedEvaluation = @($indexedLines | Where-Object {
                    $_.Index -gt $adopted[0].Index -and
                    $_.Index -le ($conflict.Index + 2) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_evaluation_requested')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_issued') -eq '0' -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $issued.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $issued.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $issued.Line -CandidateLine $_.Line -FieldName 'direction')
                })
                $legacyEvaluation = @($indexedLines | Where-Object {
                    $_.Index -gt $adopted[0].Index -and
                    $_.Index -lt $conflict.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'session_liveness_timeout_filetransfer_recovery_state_not_deferred')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'state') -eq 'receiveproofobserved' -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $issued.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $issued.Line -CandidateLine $_.Line -FieldName 'transfer_id')
                })
                if ($typedEvaluation.Count -eq 0 -and $legacyEvaluation.Count -ne 1) {
                    continue
                }

                $reservation = @($indexedLines | Where-Object {
                    $_.Index -gt $conflict.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_closure_reserved')) -and
                    (Test-TunaGuiCompletedProvenOperationMatch `
                        -AnchorLine $issued.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
                if ($reservation.Count -eq 1) {
                    $consumed = @($indexedLines | Where-Object {
                        $_.Index -gt $reservation[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_receive_recovery_operation_closure_consumed')) -and
                        (Test-TunaGuiCompletedProvenOperationMatch `
                            -AnchorLine $issued.Line `
                            -CandidateLine $_.Line)
                    } | Select-Object -First 1)
                    if ($consumed.Count -eq 1) {
                        continue
                    }
                }

                $superseded = @($indexedLines | Where-Object {
                    $_.Index -gt $conflict.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_superseded')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_receive_recovery_operation_authority_id') -eq
                        $operationAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_receive_recovery_operation_generation') -eq
                        $operationGeneration
                } | Select-Object -First 1)
                if ($superseded.Count -eq 1) {
                    $successorAuthority = Get-TunaGuiLogLineFieldValue `
                        -Line $superseded[0].Line `
                        -Name 'receive_recovery_operation_authority_id'
                    $successorGeneration = Get-TunaGuiLogLineFieldValue `
                        -Line $superseded[0].Line `
                        -Name 'receive_recovery_operation_generation'
                    $successorTerminal = @($indexedLines | Where-Object {
                        $_.Index -gt $superseded[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq
                            $successorAuthority -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq
                            $successorGeneration
                    } | Select-Object -First 1)
                    if ($successorTerminal.Count -eq 1) {
                        continue
                    }
                }

                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiReceiveRecoveryFallbackCheckpointScopeHandoffMissing {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexed = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $seenDeliveredTimeoutScopes = @{}
        foreach ($timeout in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_fallback_checkpoint_response_timeout_reissued')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'transfer_id'
            $checkpointId = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'checkpoint_request_id'
            $transportEpoch = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'transport_epoch'
            $delivered = @($indexed | Where-Object {
                    $_.Index -lt $timeout.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'delivered'
                } | Select-Object -Last 1)
            if ($delivered.Count -ne 1) { continue }
            $generation = Get-TunaGuiLogLineFieldValue -Line $delivered[0].Line -Name 'recovery_operation_generation'
            $bindingGeneration = Get-TunaGuiLogLineFieldValue -Line $delivered[0].Line -Name 'checkpoint_binding_generation'
            $deliveryGeneration = Get-TunaGuiLogLineFieldValue -Line $delivered[0].Line -Name 'checkpoint_delivery_generation'
            $fingerprint = Get-TunaGuiLogLineFieldValue -Line $delivered[0].Line -Name 'frame_fingerprint'
            $key = "$writer|$session|$transfer|$generation|$checkpointId|$bindingGeneration|$deliveryGeneration|$fingerprint|$transportEpoch".ToLowerInvariant()
            if ($seenDeliveredTimeoutScopes.ContainsKey($key)) { continue }
            $seenDeliveredTimeoutScopes[$key] = $true
            $sameScope = {
                param($item)
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'transfer_id') -eq $transfer
            }
            $binding = @($indexed | Where-Object {
                    $_.Index -lt $delivered[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_bound')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_generation') -eq $bindingGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'frame_fingerprint') -eq $fingerprint
                } | Select-Object -Last 1)
            $sent = @($indexed | Where-Object {
                    $_.Index -lt $timeout.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_regular_nkn_state_refresh_sent')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transport_epoch') -eq $transportEpoch
                } | Select-Object -First 1)
            $completion = @($indexed | Where-Object {
                    $_.Index -lt $timeout.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                    ((Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -or
                     (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_operation_generation') -eq $generation) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq 'Completed'
                } | Select-Object -Last 1)
            $proof = @($indexed | Where-Object {
                    $_.Index -lt $timeout.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_proof_decision_observed')) -and
                    ((Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -or
                     (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_operation_generation') -eq $generation) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @('Accepted', 'Idempotent', 'accepted', 'idempotent')
                } | Select-Object -Last 1)
            if ($binding.Count -ne 1 -or $sent.Count -ne 1 -or
                $completion.Count -ne 1 -or $proof.Count -ne 1) {
                continue
            }
            $advancedBeforeTimeout = @($indexed | Where-Object {
                    $_.Index -gt $delivered[0].Index -and $_.Index -lt $timeout.Index -and
                    (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -in @('accepted', 'retired')
                })
            if ($advancedBeforeTimeout.Count -gt 0) { continue }
            $recheck = @($indexed | Where-Object {
                    $_.Index -ge $timeout.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_response_timeout_recheck_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_generation') -eq $bindingGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'frame_fingerprint') -eq $fingerprint -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'status') -in @('accepted', 'idempotent')
                } | Select-Object -First 1)
            if ($recheck.Count -ne 1) { return $true }
            $redeliveryGeneration = Get-TunaGuiLogLineFieldValue -Line $recheck[0].Line -Name 'checkpoint_delivery_generation'
            $resend = @($indexed | Where-Object {
                    $_.Index -gt $recheck[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_regular_nkn_state_refresh_sent')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'request_id') -eq $checkpointId
                } | Select-Object -First 1)
            $redelivered = @($indexed | Where-Object {
                    $_.Index -gt $recheck[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_delivery_generation') -eq $redeliveryGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'delivered'
                } | Select-Object -First 1)
            $advanced = @($indexed | Where-Object {
                    $_.Index -gt $recheck[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -in @('accepted', 'retired')
                } | Select-Object -First 1)
            if ($resend.Count -ne 1 -or $redelivered.Count -ne 1 -or
                $advanced.Count -ne 1) {
                return $true
            }
            $peerResponses = @($indexed | Where-Object {
                    $_.Index -gt $redelivered[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_regular_nkn_state_refresh_received')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -ne $writer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transport_epoch') -eq $transportEpoch
                })
            $peerWriters = @($peerResponses | ForEach-Object {
                    Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id'
                } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
            $released = @($indexed | Where-Object {
                    $_.Index -gt $completion[0].Index -and
                    $_.Index -le $advanced[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                    ((Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -or
                     (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_operation_generation') -eq $generation) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Released'
                } | Select-Object -First 1)
            if ($peerResponses.Count -eq 0 -or $peerWriters.Count -ne 1 -or
                $released.Count -ne 1) {
                return $true
            }
        }
        foreach ($rejection in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'hold_boundary') -eq 'AnswerTimeout' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'expected_route') -eq 'post_tuna_fallback_v6' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Rejected' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'runtime_unlock_initial_activation_receive_recovery_scope_mismatch'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'transfer_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'expected_execution_bridge_decision_generation'
            $binding = @($indexed | Where-Object {
                    $_.Index -lt $rejection.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_bound')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -eq 'pending'
                } | Select-Object -Last 1)
            if ($binding.Count -eq 1) {
                return $true
            }
        }
        foreach ($rejection in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_outbound_sparse_worker_handoff_rejected')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route') -eq 'post_tuna_fallback_v6' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'stage') -eq 'state_refresh_sent' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'install_generation_mismatch'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'transfer_id'
            $capturedInstall = Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'install_generation'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                $capturedInstall -in @('', '0', '(none)')) {
                continue
            }
            $sameScope = {
                param($item)
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'transfer_id') -eq $transfer
            }
            $resume = @($indexed | Where-Object {
                    $_.Index -lt $rejection.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_resume_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'outcome') -in @('accepted', 'idempotent')
                } | Select-Object -Last 1)
            if ($resume.Count -ne 1) {
                continue
            }
            $generation = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'recovery_operation_generation'
            $authority = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'recovery_operation_authority_id'
            $checkpointId = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'effective_checkpoint_request_id'
            $bindingGeneration = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'checkpoint_binding_generation'
            $deliveryGeneration = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'checkpoint_delivery_generation'
            $frameFingerprint = Get-TunaGuiLogLineFieldValue -Line $resume[0].Line -Name 'frame_fingerprint'
            $sameCheckpoint = {
                param($item)
                (& $sameScope $item) -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'recovery_operation_generation') -eq $generation -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'checkpoint_binding_generation') -eq $bindingGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'frame_fingerprint') -eq $frameFingerprint
            }
            $held = @($indexed | Where-Object {
                    $_.Index -lt $resume[0].Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_delivery_generation') -eq $deliveryGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'held'
                } | Select-Object -Last 1)
            $completion = @($indexed | Where-Object {
                    $_.Index -lt $resume[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -and
                    ($authority -in @('[redacted]', '(redacted)', '(none)', 'none') -or
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq $authority) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq 'Completed'
                } | Select-Object -Last 1)
            $queued = @($indexed | Where-Object {
                    $_.Index -gt $resume[0].Index -and $_.Index -lt $rejection.Index -and
                    (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_regular_nkn_state_refresh_send_queued')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'request_id') -eq $checkpointId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source') -eq 'deferred_replay'
                } | Select-Object -First 1)
            $physicalSuccess = @($indexed | Where-Object {
                    $_.Index -gt $resume[0].Index -and $_.Index -lt $rejection.Index -and
                    (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v4_feedback_first_success')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'frame_type') -eq 'filetransfer.frontier_request.v6'
                } | Select-Object -First 1)
            $successor = @($indexed | Where-Object {
                    $_.Index -gt $resume[0].Index -and $_.Index -lt $rejection.Index -and
                    (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_outbound_sparse_worker_handoff_installed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_install_generation') -eq $capturedInstall
                } | Select-Object -First 1)
            if ($held.Count -ne 1 -or $completion.Count -ne 1 -or
                $queued.Count -ne 1 -or $physicalSuccess.Count -ne 1 -or
                $successor.Count -ne 1) {
                continue
            }
            $scopeFields = @(
                'route', 'protocol_version', 'live_route_epoch', 'runtime_generation',
                'terminal_generation', 'leg_generation', 'route_publication_generation',
                'route_commit_generation', 'data_session_generation')
            $sameRuntimeScope = $true
            foreach ($field in $scopeFields) {
                if ((Get-TunaGuiLogLineFieldValue -Line $successor[0].Line -Name $field) -ne
                    (Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name $field)) {
                    $sameRuntimeScope = $false
                    break
                }
            }
            if (-not $sameRuntimeScope) {
                continue
            }
            $delivered = @($indexed | Where-Object {
                    $_.Index -gt $resume[0].Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_delivery_generation') -eq $deliveryGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'delivered'
                } | Select-Object -First 1)
            if ($delivered.Count -eq 0) {
                return $true
            }
            $peerFrame = @($indexed | Where-Object {
                    $_.Index -gt $delivered[0].Index -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_receiver_state_received',
                        'filetransfer_receive_recovery_fallback_checkpoint_peer_frame_received'))
                } | Select-Object -First 1)
            $proof = @($indexed | Where-Object {
                    $_.Index -gt $delivered[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_proof_decision_observed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @('accepted', 'idempotent')
                } | Select-Object -First 1)
            $acceptedBinding = @($indexed | Where-Object {
                    $_.Index -gt $delivered[0].Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -in @('accepted', 'retired')
                } | Select-Object -First 1)
            $released = @($indexed | Where-Object {
                    $_.Index -gt $delivered[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Released'
                } | Select-Object -First 1)
            if ($peerFrame.Count -eq 0 -or $proof.Count -eq 0 -or
                $acceptedBinding.Count -eq 0 -or $released.Count -eq 0) {
                return $true
            }
        }
        foreach ($retirement in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -eq 'retired' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'tail_reconciliation_forced'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'transfer_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'recovery_operation_generation'
            $checkpointId = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'effective_checkpoint_request_id'
            $bindingGeneration = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'checkpoint_binding_generation'
            $frameFingerprint = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'frame_fingerprint'
            $transportEpoch = Get-TunaGuiLogLineFieldValue -Line $retirement.Line -Name 'transport_epoch'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                $generation -in @('', '0', '(none)') -or
                [string]::IsNullOrWhiteSpace($checkpointId) -or
                $bindingGeneration -in @('', '0', '(none)') -or
                [string]::IsNullOrWhiteSpace($frameFingerprint) -or
                $transportEpoch -in @('', '0', '(none)')) {
                continue
            }
            $sameScope = {
                param($item)
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'transfer_id') -eq $transfer
            }
            $sameCheckpoint = {
                param($item)
                (& $sameScope $item) -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'recovery_operation_generation') -eq $generation -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'effective_checkpoint_request_id') -eq $checkpointId -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'checkpoint_binding_generation') -eq $bindingGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'frame_fingerprint') -eq $frameFingerprint
            }
            $binding = @($indexed | Where-Object {
                    $_.Index -lt $retirement.Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_bound')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_binding_state') -eq 'pending' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transport_epoch') -eq $transportEpoch
                } | Select-Object -Last 1)
            $held = @($indexed | Where-Object {
                    $_.Index -lt $retirement.Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'held' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @('accepted', 'idempotent')
                } | Select-Object -Last 1)
            if ($binding.Count -ne 1 -or $held.Count -ne 1) {
                continue
            }
            $deliveryGeneration = Get-TunaGuiLogLineFieldValue -Line $held[0].Line -Name 'checkpoint_delivery_generation'
            $started = @($indexed | Where-Object {
                    $_.Index -lt $binding[0].Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_issued',
                        'filetransfer_receive_recovery_operation_execution_start_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route') -eq 'post_tuna_fallback_v6'
                })
            $resume = @($indexed | Where-Object {
                    $_.Index -gt $held[0].Index -and $_.Index -lt $retirement.Index -and
                    (& $sameCheckpoint $_) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_delivery_generation') -eq $deliveryGeneration -and
                    ((Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_delivery_resumed')) -or
                        ((Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'delivery_state') -eq 'delivered'))
                })
            $bindingInvalidated = @($indexed | Where-Object {
                    $_.Index -gt $retirement.Index -and (& $sameCheckpoint $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_fallback_checkpoint_invalidated')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'runtime_scope_replaced'
                } | Select-Object -First 1)
            $operationInvalidated = @($indexed | Where-Object {
                    $_.Index -gt $retirement.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_invalidated')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'runtime_scope_replaced'
                } | Select-Object -First 1)
            if ($started.Count -gt 0 -and $resume.Count -eq 0 -and
                $bindingInvalidated.Count -eq 1 -and $operationInvalidated.Count -eq 1) {
                return $true
            }
        }
        foreach ($candidate in @($indexed | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_invalidated')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route') -eq 'post_tuna_fallback_v6' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'runtime_scope_replaced'
                })) {
            $writer = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'transfer_id'
            $authority = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'receive_recovery_operation_authority_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'receive_recovery_operation_generation'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                [string]::IsNullOrWhiteSpace($authority) -or
                $generation -in @('', '0', '(none)')) {
                continue
            }
            $sameScope = {
                param($item)
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $item.Line -Name 'transfer_id') -eq $transfer
            }
            $started = @($indexed | Where-Object {
                    $_.Index -lt $candidate.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_issued',
                        'filetransfer_receive_recovery_operation_execution_start_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq $generation
                })
            $held = @($indexed | Where-Object {
                    $_.Index -lt $candidate.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'runtime_unlock_initial_activation_receive_recovery_hold_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Held'
                })
            $request = @($indexed | Where-Object {
                    $_.Index -lt $candidate.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_v6_regular_nkn_state_refresh_requested'))
                } | Select-Object -Last 1)
            if ($started.Count -eq 0 -or $held.Count -eq 0 -or $request.Count -ne 1) {
                continue
            }
            $requestId = Get-TunaGuiLogLineFieldValue -Line $request[0].Line -Name 'request_id'
            $checkpoint = @($indexed | Where-Object {
                    $_.Index -gt $candidate.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_fallback_checkpoint_requested',
                        'filetransfer_clean_fallback_checkpoint_requested')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'checkpoint_request_id') -eq $requestId
                } | Select-Object -First 1)
            $lateWorker = @($indexed | Where-Object {
                    $_.Index -gt $candidate.Index -and (& $sameScope $_) -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'nkn_bridge_recovery_execution_completion_late')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'total_deadline_expired') -eq '0'
                } | Select-Object -First 1)
            $lostTransaction = @($indexed | Where-Object {
                    $_.Index -gt $candidate.Index -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writer -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_transaction_failed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq 'runtime_scope_replaced'
                } | Select-Object -First 1)
            if ($checkpoint.Count -gt 0 -and $lateWorker.Count -gt 0 -and $lostTransaction.Count -gt 0) {
                return $true
            }
        }
        return $false
    }

    function Test-TunaGuiReceiveRecoveryCompletedUnprovenSuccessorMissing {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )

        function Test-TunaGuiReceiveRecoveryMeaningful {
            param([AllowNull()][AllowEmptyString()][string]$Value)

            return -not [string]::IsNullOrWhiteSpace($Value) -and
                $Value -notin @('(none)', 'none', '(missing)', '__missing__', '0')
        }

        function Get-TunaGuiReceiveRecoveryOperationGeneration {
            param([Parameter(Mandatory = $true)][string]$Line)

            foreach ($name in @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation',
                    'operation_generation')) {
                $value = Get-TunaGuiLogLineFieldValue -Line $Line -Name $name
                if (-not [string]::IsNullOrWhiteSpace($value)) {
                    return $value
                }
            }
            return ''
        }

        function Get-TunaGuiReceiveRecoveryOperationAuthority {
            param([Parameter(Mandatory = $true)][string]$Line)

            foreach ($name in @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')) {
                $value = Get-TunaGuiLogLineFieldValue -Line $Line -Name $name
                if (-not [string]::IsNullOrWhiteSpace($value)) {
                    return $value
                }
            }
            return ''
        }

        function Test-TunaGuiReceiveRecoveryOperationMatch {
            param(
                [Parameter(Mandatory = $true)][string]$AnchorLine,
                [Parameter(Mandatory = $true)][string]$CandidateLine
            )

            $anchorAuthority =
                Get-TunaGuiReceiveRecoveryOperationAuthority -Line $AnchorLine
            $candidateAuthority =
                Get-TunaGuiReceiveRecoveryOperationAuthority -Line $CandidateLine
            $anchorGeneration =
                Get-TunaGuiReceiveRecoveryOperationGeneration -Line $AnchorLine
            $candidateGeneration =
                Get-TunaGuiReceiveRecoveryOperationGeneration -Line $CandidateLine
            if (-not (Test-TunaGuiReceiveRecoveryMeaningful $anchorAuthority) -or
                -not (Test-TunaGuiReceiveRecoveryMeaningful $candidateAuthority) -or
                -not (Test-TunaGuiReceiveRecoveryMeaningful $anchorGeneration) -or
                -not (Test-TunaGuiReceiveRecoveryMeaningful $candidateGeneration) -or
                $anchorAuthority -ne $candidateAuthority -or
                $anchorGeneration -ne $candidateGeneration) {
                return $false
            }

            foreach ($field in @(
                    'session_id',
                    'transfer_id',
                    'direction',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'route_commit_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'bridge_decision_generation',
                    'checkpoint_request_id',
                    'data_session_identity',
                    'data_session_generation',
                    'recovery_liveness_lease_authority_id',
                    'recovery_liveness_lease_generation')) {
                $expected =
                    Get-TunaGuiLogLineFieldValue -Line $AnchorLine -Name $field
                $actual =
                    Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $field
                if ([string]::IsNullOrWhiteSpace($expected) -or
                    [string]::IsNullOrWhiteSpace($actual) -or
                    -not [string]::Equals(
                        $expected,
                        $actual,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiReceiveRecoveryRejectionScope {
            param(
                [Parameter(Mandatory = $true)][string]$OperationLine,
                [Parameter(Mandatory = $true)][string]$RejectionLine
            )

            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                $expected =
                    Get-TunaGuiLogLineFieldValue -Line $OperationLine -Name $field
                $actual =
                    Get-TunaGuiLogLineFieldValue -Line $RejectionLine -Name $field
                if ([string]::IsNullOrWhiteSpace($expected) -or
                    [string]::IsNullOrWhiteSpace($actual) -or
                    -not [string]::Equals(
                        $expected,
                        $actual,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }

            foreach ($mapping in @(
                    [pscustomobject]@{
                        Operation = 'route'
                        Rejection = @('current_route', 'attempted_route')
                    },
                    [pscustomobject]@{
                        Operation = 'protocol_version'
                        Rejection = @('current_protocol_version', 'attempted_protocol_version')
                    },
                    [pscustomobject]@{
                        Operation = 'live_route_epoch'
                        Rejection = @('current_live_route_epoch', 'attempted_live_route_epoch')
                    },
                    [pscustomobject]@{
                        Operation = 'runtime_generation'
                        Rejection = @('current_runtime_generation', 'attempted_runtime_generation')
                    },
                    [pscustomobject]@{
                        Operation = 'terminal_generation'
                        Rejection = @('current_terminal_generation', 'attempted_terminal_generation')
                    },
                    [pscustomobject]@{
                        Operation = 'leg_generation'
                        Rejection = @('attempted_leg_generation')
                    },
                    [pscustomobject]@{
                        Operation = 'transport_epoch'
                        Rejection = @('attempted_transport_epoch')
                    },
                    [pscustomobject]@{
                        Operation = 'bridge_recovery_generation'
                        Rejection = @('attempted_bridge_recovery_generation')
                    })) {
                $expected = Get-TunaGuiLogLineFieldValue `
                    -Line $OperationLine `
                    -Name $mapping.Operation
                $actual = ''
                foreach ($candidateName in $mapping.Rejection) {
                    $actual = Get-TunaGuiLogLineFieldValue `
                        -Line $RejectionLine `
                        -Name $candidateName
                    if (-not [string]::IsNullOrWhiteSpace($actual)) {
                        break
                    }
                }
                if (-not [string]::IsNullOrWhiteSpace($actual) -and
                    ([string]::IsNullOrWhiteSpace($expected) -or
                     -not [string]::Equals(
                        $expected,
                        $actual,
                        [System.StringComparison]::OrdinalIgnoreCase))) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiReceiveRecoverySupersessionCompleted {
            param(
                [Parameter(Mandatory = $true)]$Rejection,
                [Parameter(Mandatory = $true)]$Issued,
                [Parameter(Mandatory = $true)][string]$ClosureGeneration
            )

            $operationAuthority =
                Get-TunaGuiReceiveRecoveryOperationAuthority -Line $Issued.Line
            $operationGeneration =
                Get-TunaGuiReceiveRecoveryOperationGeneration -Line $Issued.Line
            $supersession = @($indexedLines | Where-Object {
                $_.Index -gt $Rejection.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_superseded')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'predecessor_receive_recovery_operation_authority_id') -eq
                        $operationAuthority -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'predecessor_receive_recovery_operation_generation') -eq
                        $operationGeneration -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'predecessor_closure_generation') -eq
                        $ClosureGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'session_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'transfer_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'direction')
            } | Select-Object -First 1)
            if ($supersession.Count -eq 0) {
                return $false
            }

            $successorAuthority = Get-TunaGuiLogLineFieldValue `
                -Line $supersession[0].Line `
                -Name 'successor_receive_recovery_operation_authority_id'
            $successorGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $supersession[0].Line `
                -Name 'successor_receive_recovery_operation_generation'
            if (-not (Test-TunaGuiReceiveRecoveryMeaningful $successorAuthority) -or
                -not (Test-TunaGuiReceiveRecoveryMeaningful $successorGeneration)) {
                return $false
            }

            $successor = @($indexedLines | Where-Object {
                $_.Index -gt $supersession[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_issued')) -and
                (Get-TunaGuiReceiveRecoveryOperationAuthority -Line $_.Line) -eq
                    $successorAuthority -and
                (Get-TunaGuiReceiveRecoveryOperationGeneration -Line $_.Line) -eq
                    $successorGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'session_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'transfer_id') -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name 'direction')
            } | Select-Object -First 1)
            if ($successor.Count -eq 0) {
                return $false
            }

            $successorStart = @($indexedLines | Where-Object {
                $_.Index -gt $successor[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_start_decided',
                    'filetransfer_receive_recovery_operation_execution_started')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'execution_start_status') -in @(
                        'Started',
                        'Idempotent',
                        'Accepted') -and
                (Test-TunaGuiReceiveRecoveryOperationMatch `
                    -AnchorLine $successor[0].Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($successorStart.Count -eq 0) {
                return $false
            }

            $successorReceipt = @($indexedLines | Where-Object {
                $_.Index -gt $successorStart[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_receipt_applied',
                    'filetransfer_receive_recovery_operation_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'execution_outcome') -in @(
                        'Completed',
                        'Exhausted',
                        'Discarded') -and
                (Test-TunaGuiReceiveRecoveryOperationMatch `
                    -AnchorLine $successor[0].Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            return $successorReceipt.Count -gt 0
        }

        $issuedEvents = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_receive_recovery_operation_issued')) -and
            (Test-TunaGuiReceiveRecoveryMeaningful (
                Get-TunaGuiReceiveRecoveryOperationAuthority -Line $_.Line)) -and
            (Test-TunaGuiReceiveRecoveryMeaningful (
                Get-TunaGuiReceiveRecoveryOperationGeneration -Line $_.Line))
        })
        $rejections = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_recovery_authority_rejected')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'action_kind') -eq
                'ReceiveRecoveryOperation' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'rejection_reason') -eq
                'filetransfer_receive_recovery_operation_conflict' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'attempted_action') -in @(
                'bridge_ping_timeout',
                'bridge_receive_stall',
                'receive_stall',
                'ping_timeout')
        })

        foreach ($rejection in $rejections) {
            $writer =
                Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'log_writer_id'
            $transfer =
                Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'transfer_id'
            $direction =
                Get-TunaGuiLogLineFieldValue -Line $rejection.Line -Name 'direction'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                [string]::IsNullOrWhiteSpace($direction)) {
                continue
            }

            $health = @($indexedLines | Where-Object {
                $_.Index -lt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_evaluation_requested')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'observation_kind') -in @(
                    'ping_timeout',
                    'receive_stall') -and
                (Test-TunaGuiReceiveRecoveryMeaningful (
                    Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'observation_generation'))
            } | Select-Object -Last 1)
            if ($health.Count -eq 0) {
                continue
            }
            $observationGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $health[0].Line `
                -Name 'observation_generation'
            $evaluationDecision = @($indexedLines | Where-Object {
                $_.Index -gt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_evaluation_requested')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    $writer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                    $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                    $direction -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'observation_generation') -eq $observationGeneration -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'receive_recovery_operation_issued') -eq '0'
            } | Select-Object -First 1)
            if ($evaluationDecision.Count -eq 0) {
                continue
            }

            $eligibleOperations = New-Object System.Collections.Generic.List[object]
            foreach ($issued in @($issuedEvents | Where-Object {
                    $_.Index -lt $health[0].Index -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                        $writer -and
                    (Test-TunaGuiReceiveRecoveryRejectionScope `
                        -OperationLine $_.Line `
                        -RejectionLine $rejection.Line)
                })) {
                $operationEvents = @($indexedLines | Where-Object {
                    $_.Index -gt $issued.Index -and
                    $_.Index -lt $rejection.Index -and
                    (Test-TunaGuiReceiveRecoveryOperationMatch `
                        -AnchorLine $issued.Line `
                        -CandidateLine $_.Line)
                })
                $start = @($operationEvents | Where-Object {
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_execution_start_decided',
                        'filetransfer_receive_recovery_operation_execution_started')) -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'execution_start_status') -in @(
                            'Started',
                            'Idempotent',
                            'Accepted')
                } | Select-Object -First 1)
                if ($start.Count -eq 0) {
                    continue
                }
                $receipt = @($operationEvents | Where-Object {
                    $_.Index -gt $start[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_execution_receipt_applied',
                        'filetransfer_receive_recovery_operation_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'execution_outcome') -eq 'Completed' -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'execution_state') -eq 'Completed' -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'proof_identity') -in @('', '(none)', 'none') -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'proof_observed_utc_ms') -in @('', '0')
                } | Select-Object -First 1)
                if ($receipt.Count -eq 0) {
                    continue
                }
                $retained = @($operationEvents | Where-Object {
                    $_.Index -gt $receipt[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_receive_recovery_operation_closure_retained')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq
                        'Retained' -and
                    (Test-TunaGuiReceiveRecoveryMeaningful (
                        Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'closure_generation'))
                } | Select-Object -First 1)
                if ($retained.Count -eq 0 -or $retained[0].Index -ge $health[0].Index) {
                    continue
                }

                $disqualifying = @($operationEvents | Where-Object {
                    $_.Index -gt $retained[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_receive_recovery_operation_proof_observed',
                        'filetransfer_receive_recovery_operation_receive_proof_observed',
                        'filetransfer_receive_recovery_operation_closure_adopted',
                        'filetransfer_receive_recovery_operation_closure_reserved',
                        'filetransfer_receive_recovery_operation_closure_consumed',
                        'filetransfer_receive_recovery_operation_invalidated'))
                })
                if ($disqualifying.Count -gt 0) {
                    continue
                }

                $eligibleOperations.Add([pscustomobject]@{
                    Issued = $issued
                    Retained = $retained[0]
                }) | Out-Null
            }

            # Legacy rejection events carry no operation identity. They may attach
            # only when one complete same-writer operation window is available.
            if ($eligibleOperations.Count -ne 1) {
                continue
            }

            $operation = $eligibleOperations[0]
            $proof = @($indexedLines | Where-Object {
                $_.Index -gt $rejection.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_proof_observed',
                    'filetransfer_receive_recovery_operation_receive_proof_observed')) -and
                (Test-TunaGuiReceiveRecoveryMeaningful (
                    Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'proof_identity')) -and
                (Test-TunaGuiReceiveRecoveryOperationMatch `
                    -AnchorLine $operation.Issued.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($proof.Count -gt 0) {
                $adoption = @($indexedLines | Where-Object {
                    $_.Index -gt $proof[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_receive_recovery_operation_closure_adopted')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq
                        'Adopted' -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'closure_generation') -eq
                            (Get-TunaGuiLogLineFieldValue `
                                -Line $operation.Retained.Line `
                                -Name 'closure_generation') -and
                    (Test-TunaGuiReceiveRecoveryOperationMatch `
                        -AnchorLine $operation.Issued.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
                if ($adoption.Count -gt 0) {
                    continue
                }
            }

            if (Test-TunaGuiReceiveRecoverySupersessionCompleted `
                    -Rejection $rejection `
                    -Issued $operation.Issued `
                    -ClosureGeneration (
                        Get-TunaGuiLogLineFieldValue `
                            -Line $operation.Retained.Line `
                            -Name 'closure_generation')) {
                continue
            }

            return $true
        }

        return $false
    }

    function Test-TunaGuiPostTunaLateSubmissionObservationFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexed = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        foreach ($failure in @($indexed | Where-Object {
                Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_v4_sender_failed')
            })) {
            $issued = @($indexed | Where-Object {
                $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_receive_recovery_operation_issued')) -and
                ((Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route').ToLowerInvariant() -replace '[^a-z0-9]', '') -eq 'posttunafallbackv6' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'protocol_version') -eq '6' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction').ToLowerInvariant() -eq 'outbound' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $failure.Line -Name 'log_writer_id')
            } | Select-Object -Last 1)
            if ($issued.Count -ne 1) { continue }
            $authority = Get-TunaGuiLogLineFieldValue -Line $issued[0].Line -Name 'receive_recovery_operation_authority_id'
            $generation = Get-TunaGuiLogLineFieldValue -Line $issued[0].Line -Name 'receive_recovery_operation_generation'
            $matchesOperation = {
                param($candidate)
                (Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'receive_recovery_operation_authority_id') -eq $authority -and
                (Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'receive_recovery_operation_generation') -eq $generation
            }
            $deferral = @($indexed | Where-Object {
                $_.Index -gt $issued[0].Index -and $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_post_tuna_fallback_recovery_submission_failure_deferred')) -and
                (& $matchesOperation $_)
            } | Select-Object -First 1)
            $completion = @($indexed | Where-Object {
                $deferral.Count -eq 1 -and $_.Index -gt $deferral[0].Index -and $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                (& $matchesOperation $_) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_state').ToLowerInvariant() -eq 'completed' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'proof_identity') -notin @('', '(none)')
            } | Select-Object -First 1)
            $resume = @($indexed | Where-Object {
                $completion.Count -eq 1 -and $_.Index -gt $completion[0].Index -and $_.Index -lt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_post_tuna_fallback_recovery_submission_failure_resumed')) -and
                (& $matchesOperation $_)
            } | Select-Object -First 1)
            $invalidation = @($indexed | Where-Object {
                $_.Index -gt $failure.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_receive_recovery_operation_invalidated')) -and
                (& $matchesOperation $_) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_reason') -eq 'terminal_state'
            } | Select-Object -First 1)
            if ($deferral.Count -eq 1 -and $completion.Count -eq 1 -and
                $resume.Count -eq 1 -and $invalidation.Count -eq 1) {
                return $true
            }
        }
        return $false
    }

    function Test-TunaGuiBridgeRecoveryExecutionPayloadHoldFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )

        function Get-TunaGuiNormalizedBridgeRecoveryRoute {
            param([string]$Line, [string]$Name)
            return (Get-TunaGuiLogLineFieldValue -Line $Line -Name $Name).
                ToLowerInvariant() -replace '[^a-z0-9]', ''
        }

        function Test-TunaGuiBridgeRecoveryTransferIdentity {
            param(
                [string]$SourceLine,
                [string]$CandidateLine,
                [switch]$RequireDirection,
                [switch]$RequireWriter
            )

            foreach ($field in @('session_id', 'transfer_id')) {
                if (-not (Test-TunaGuiLogLineFieldMatch `
                        -SourceLine $SourceLine `
                        -CandidateLine $CandidateLine `
                        -FieldName $field)) {
                    return $false
                }
            }
            if ($RequireDirection -and
                -not (Test-TunaGuiLogLineFieldMatch `
                    -SourceLine $SourceLine `
                    -CandidateLine $CandidateLine `
                    -FieldName 'direction')) {
                return $false
            }
            if ($RequireWriter) {
                $sourceWriter = Get-TunaGuiLogLineFieldValue -Line $SourceLine -Name 'log_writer_id'
                $candidateWriter = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name 'log_writer_id'
                if ([string]::IsNullOrWhiteSpace($sourceWriter) -or
                    [string]::IsNullOrWhiteSpace($candidateWriter) -or
                    $sourceWriter -ne $candidateWriter) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiBridgeRecoveryCommandScope {
            param(
                [string]$CommandLine,
                [string]$CandidateLine,
                [switch]$SourcePrefixed,
                [switch]$IncludeDecision
            )

            if (-not (Test-TunaGuiBridgeRecoveryTransferIdentity `
                    -SourceLine $CommandLine `
                    -CandidateLine $CandidateLine `
                    -RequireDirection)) {
                return $false
            }
            $candidateRouteField = if ($SourcePrefixed) { 'source_route' } else { 'route' }
            if ((Get-TunaGuiNormalizedBridgeRecoveryRoute -Line $CommandLine -Name 'route') -ne
                (Get-TunaGuiNormalizedBridgeRecoveryRoute -Line $CandidateLine -Name $candidateRouteField)) {
                return $false
            }
            foreach ($field in @(
                    'protocol_version',
                    'live_route_epoch',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation')) {
                $candidateField = if ($SourcePrefixed) { "source_$field" } else { $field }
                $expected = Get-TunaGuiLogLineFieldValue -Line $CommandLine -Name $field
                $actual = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $candidateField
                if ([string]::IsNullOrWhiteSpace($expected) -or
                    [string]::IsNullOrWhiteSpace($actual) -or
                    $expected -ne $actual) {
                    return $false
                }
            }
            if ($IncludeDecision -and
                -not (Test-TunaGuiLogLineFieldMatch `
                    -SourceLine $CommandLine `
                    -CandidateLine $CandidateLine `
                    -FieldName 'bridge_decision_generation')) {
                return $false
            }
            return $true
        }

        $commands = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_bridge_recovery_execution_command_issued')
        })
        $senderFailures = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_v4_sender_failed')
        })
        foreach ($senderFailure in $senderFailures) {
            $command = @($commands | Where-Object {
                $_.Index -lt $senderFailure.Index -and
                (Test-TunaGuiBridgeRecoveryTransferIdentity `
                    -SourceLine $_.Line `
                    -CandidateLine $senderFailure.Line `
                    -RequireWriter)
            } | Select-Object -Last 1)
            if ($command.Count -eq 0) {
                continue
            }

            $start = @($indexedLines | Where-Object {
                $_.Index -gt $command[0].Index -and
                $_.Index -lt $senderFailure.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_execution_started')) -and
                (Test-TunaGuiBridgeRecoveryCommandScope `
                    -CommandLine $command[0].Line `
                    -CandidateLine $_.Line `
                    -IncludeDecision) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $command[0].Line `
                        -Name 'recovery_liveness_lease_generation')
            } | Select-Object -First 1)
            if ($start.Count -eq 0) {
                continue
            }

            $barrier = @($indexedLines | Where-Object {
                $_.Index -gt $start[0].Index -and
                $_.Index -lt $senderFailure.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_submission_barrier_closed')) -and
                (Test-TunaGuiBridgeRecoveryCommandScope `
                    -CommandLine $command[0].Line `
                    -CandidateLine $_.Line `
                    -IncludeDecision) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $command[0].Line `
                        -Name 'recovery_liveness_lease_generation')
            } | Select-Object -First 1)
            if ($barrier.Count -eq 0) {
                continue
            }
            $submissionEpoch = Get-TunaGuiLogLineFieldValue `
                -Line $barrier[0].Line `
                -Name 'submission_epoch'
            if ([string]::IsNullOrWhiteSpace($submissionEpoch) -or $submissionEpoch -eq '0') {
                continue
            }

            $hardDecision = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                $_.Index -lt $senderFailure.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_execution_hard_restart_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Started' -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'remaining_total_ms') -gt 0 -and
                (Test-TunaGuiBridgeRecoveryCommandScope `
                    -CommandLine $command[0].Line `
                    -CandidateLine $_.Line `
                    -IncludeDecision) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $command[0].Line `
                        -Name 'recovery_liveness_lease_generation')
            } | Select-Object -First 1)
            if ($hardDecision.Count -eq 0) {
                continue
            }

            $barrierTerminal = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'nkn_bridge_recovery_submission_barrier_released',
                    'nkn_bridge_recovery_submission_barrier_invalidated',
                    'nkn_bridge_recovery_execution_completed',
                    'nkn_bridge_recovery_execution_completion_late')) -and
                (Test-TunaGuiBridgeRecoveryTransferIdentity `
                    -SourceLine $command[0].Line `
                    -CandidateLine $_.Line `
                    -RequireDirection `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($barrierTerminal.Count -gt 0 -and
                $senderFailure.Index -ge $barrierTerminal[0].Index) {
                continue
            }

            $qualifyingBindings = New-Object System.Collections.Generic.List[object]
            foreach ($binding in @($indexedLines | Where-Object {
                    $_.Index -gt $barrier[0].Index -and
                    $_.Index -lt $senderFailure.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_committed')) -and
                    (Test-TunaGuiBridgeRecoveryCommandScope `
                        -CommandLine $command[0].Line `
                        -CandidateLine $_.Line `
                        -IncludeDecision)
                })) {
                $authorityId = Get-TunaGuiLogLineFieldValue -Line $binding.Line -Name 'authority_id'
                $installGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $binding.Line `
                    -Name 'install_generation'
                $repairKey = Get-TunaGuiLogLineFieldValue `
                    -Line $binding.Line `
                    -Name 'repair_request_key'
                if ([string]::IsNullOrWhiteSpace($authorityId) -or
                    [string]::IsNullOrWhiteSpace($installGeneration) -or
                    $installGeneration -eq '0' -or
                    [string]::IsNullOrWhiteSpace($repairKey)) {
                    continue
                }
                $grant = @($indexedLines | Where-Object {
                    $_.Index -gt $binding.Index -and
                    $_.Index -lt $senderFailure.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_authority_granted')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authorityId -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq
                        $repairKey -and
                    (Test-TunaGuiBridgeRecoveryCommandScope `
                        -CommandLine $command[0].Line `
                        -CandidateLine $_.Line `
                        -IncludeDecision)
                } | Select-Object -First 1)
                if ($grant.Count -eq 0) {
                    continue
                }

                $linkedFailure = $false
                foreach ($lease in @($indexedLines | Where-Object {
                        $_.Index -gt $hardDecision[0].Index -and
                        $_.Index -lt $senderFailure.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_physical_send_lease_registered')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'send_kind') -eq
                            'RegularV4Repair' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_send') -eq '1' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq
                            $repairKey -and
                        (Test-TunaGuiBridgeRecoveryCommandScope `
                            -CommandLine $command[0].Line `
                            -CandidateLine $_.Line `
                            -SourcePrefixed) -and
                        (Test-TunaGuiBridgeRecoveryTransferIdentity `
                            -SourceLine $command[0].Line `
                            -CandidateLine $_.Line `
                            -RequireWriter)
                    })) {
                    $deliveryFailure = @($indexedLines | Where-Object {
                        $_.Index -gt $lease.Index -and
                        $_.Index -lt $senderFailure.Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @('filetransfer_v4_repair_delivery_both_failed')) -and
                        (Test-TunaGuiBridgeRecoveryTransferIdentity `
                            -SourceLine $command[0].Line `
                            -CandidateLine $_.Line `
                            -RequireWriter)
                    } | Select-Object -First 1)
                    if ($deliveryFailure.Count -eq 0) {
                        continue
                    }
                    $rejects = @($indexedLines | Where-Object {
                        $_.Index -gt $lease.Index -and
                        $_.Index -lt $deliveryFailure[0].Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @('nkn_bridge_submission_rejected')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'stage') -eq 'pre_wait' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                            'bridge_submission_epoch_not_ready' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'submission_epoch') -eq
                            $submissionEpoch -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_barrier_active') -eq '1' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $command[0].Line -Name 'log_writer_id')
                    })
                    $channels = @($rejects | ForEach-Object {
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'channel').ToLowerInvariant()
                    } | Select-Object -Unique)
                    if ($channels -contains 'control' -and $channels -contains 'bulk') {
                        $linkedFailure = $true
                        break
                    }
                }
                if ($linkedFailure) {
                    $qualifyingBindings.Add($binding) | Out-Null
                }
            }

            $bindingKeys = @($qualifyingBindings | ForEach-Object {
                [string]::Join('|', @(
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key')))
            } | Select-Object -Unique)
            if ($bindingKeys.Count -eq 1) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiReceiveRecoveryCompletedUnprovenPayloadHoldFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        [string[]]$scopeFields = @(
            'log_writer_id',
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'route_publication_generation',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'data_session_generation')

        function Test-TunaGuiCompletedUnprovenPayloadScope {
            param(
                [Parameter(Mandatory = $true)][string]$Anchor,
                [Parameter(Mandatory = $true)][string]$Candidate
            )

            foreach ($field in $scopeFields) {
                $left =
                    Get-TunaGuiLogLineFieldValue -Line $Anchor -Name $field
                $right =
                    Get-TunaGuiLogLineFieldValue -Line $Candidate -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    -not [string]::Equals(
                        $left,
                        $right,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiCompletedUnprovenPayloadOperation {
            param(
                [Parameter(Mandatory = $true)][string]$Issued,
                [Parameter(Mandatory = $true)][string]$Candidate
            )

            if (-not (Test-TunaGuiCompletedUnprovenPayloadScope `
                    -Anchor $Issued `
                    -Candidate $Candidate)) {
                return $false
            }
            $generation = Get-TunaGuiLogLineFieldValue `
                -Line $Issued `
                -Name 'receive_recovery_operation_generation'
            $candidateGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $Candidate `
                -Name 'recovery_operation_generation'
            if ([string]::IsNullOrWhiteSpace($candidateGeneration)) {
                $candidateGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $Candidate `
                    -Name 'receive_recovery_operation_generation'
            }
            return -not [string]::IsNullOrWhiteSpace($generation) -and
                $generation -eq $candidateGeneration
        }

        $supersessions = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_receive_recovery_operation_superseded')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                'outbound' -and
            (Get-TunaGuiLogLineFieldValue `
                -Line $_.Line `
                -Name 'decision_reason') -eq
                'completed_unproven_receive_recovery_superseded_by_newer_health_observation' -and
            -not [string]::IsNullOrWhiteSpace(
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'health_evaluation_kind'))
        })
        foreach ($supersession in $supersessions) {
            $predecessorGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $supersession.Line `
                -Name 'predecessor_receive_recovery_operation_generation'
            $issued = @($indexedLines | Where-Object {
                $_.Index -lt $supersession.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_issued')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'receive_recovery_operation_generation') -eq
                    $predecessorGeneration -and
                (Test-TunaGuiCompletedUnprovenPayloadScope `
                    -Anchor $_.Line `
                    -Candidate $supersession.Line)
            } | Select-Object -Last 1)
            if ($issued.Count -ne 1) {
                continue
            }

            $operationLines = @($indexedLines | Where-Object {
                $_.Index -gt $issued[0].Index -and
                $_.Index -lt $supersession.Index -and
                (Test-TunaGuiCompletedUnprovenPayloadOperation `
                    -Issued $issued[0].Line `
                    -Candidate $_.Line)
            })
            $start = @($operationLines | Where-Object {
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_start_decided',
                    'filetransfer_receive_recovery_operation_execution_started')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'execution_start_status') -in @(
                        'Started',
                        'Idempotent',
                        'Accepted')
            } | Select-Object -First 1)
            $held = @($operationLines | Where-Object {
                Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_bridge_recovery_payload_submission_held')
            } | Select-Object -First 1)
            $receipt = @($operationLines | Where-Object {
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_receipt_applied',
                    'filetransfer_receive_recovery_operation_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'execution_outcome') -eq 'Completed' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Retained'
            } | Select-Object -First 1)
            $retained = @($operationLines | Where-Object {
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_retained')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Retained'
            } | Select-Object -First 1)
            $resume = @($operationLines | Where-Object {
                Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_bridge_recovery_payload_submission_resumed')
            } | Select-Object -First 1)
            if ($start.Count -ne 1 -or
                $held.Count -ne 1 -or
                $receipt.Count -ne 1 -or
                $retained.Count -ne 1 -or
                $resume.Count -ne 1 -or
                $resume[0].Index -le $retained[0].Index) {
                continue
            }

            $successorGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $supersession.Line `
                -Name 'successor_receive_recovery_operation_generation'
            $successor = @($indexedLines | Where-Object {
                $_.Index -gt $supersession.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_issued')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'receive_recovery_operation_generation') -eq
                    $successorGeneration -and
                (Test-TunaGuiCompletedUnprovenPayloadScope `
                    -Anchor $issued[0].Line `
                    -Candidate $_.Line)
            } | Select-Object -First 1)
            if ($successor.Count -ne 1) {
                continue
            }
            $successorStarted = @($indexedLines | Where-Object {
                $_.Index -gt $successor[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_receive_recovery_operation_execution_start_decided',
                    'filetransfer_receive_recovery_operation_execution_started')) -and
                (Test-TunaGuiCompletedUnprovenPayloadOperation `
                    -Issued $successor[0].Line `
                    -Candidate $_.Line)
            } | Select-Object -First 1)
            if ($successorStarted.Count -eq 1) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiInitialActivationHoldReleasedPathLeaseExpired {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $timeouts = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('tuna_listener_sidecar_event')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'sidecar_event') -eq 'error' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'sidecar_reason') -match
                'Tuna accept failed: accept timed out'
        })
        foreach ($timeout in $timeouts) {
            $writerId = Get-TunaGuiLogLineFieldValue -Line $timeout.Line -Name 'log_writer_id'
            $failure = @($indexedLines | Where-Object {
                $_.Index -gt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'tuna_path_lease_failed',
                    'tuna_path_lease_sidecar_unavailable')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId
            } | Select-Object -First 2)
            if ($failure.Count -ne 1) { continue }

            $resume = @($indexedLines | Where-Object {
                $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_offer_envelope_refresh_physical_resume')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'boundary') -in @(
                    'PeerResponseTimeout',
                    'AnswerTimeout') -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'refresh_generation') -gt 0
            } | Select-Object -Last 2)
            if ($resume.Count -ne 1) { continue }

            $refreshGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $resume[0].Line `
                -Name 'refresh_generation'
            $refresh = @($indexedLines | Where-Object {
                $_.Index -lt $resume[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_offer_envelope_refresh_committed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'refresh_generation') -eq
                    $refreshGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @(
                    'Accepted',
                    'Idempotent')
            } | Select-Object -Last 1)
            if ($refresh.Count -ne 1) { continue }

            $submission = @($indexedLines | Where-Object {
                $_.Index -gt $resume[0].Index -and $_.Index -lt $timeout.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated',
                    'runtime_unlock_initial_activation_receive_recovery_hold_post_prevalidation_submission')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $writerId
            })
            if ($submission.Count -eq 0) { return $true }
        }
        return $false
    }

    function Test-TunaGuiReceiveRecoveryCompletedRetainedProofStatePublicationFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )

        function Get-ProofStateFieldValue {
            param(
                [Parameter(Mandatory = $true)][string]$Line,
                [Parameter(Mandatory = $true)][string[]]$Names
            )

            foreach ($name in $Names) {
                $value =
                    Get-TunaGuiLogLineFieldValue -Line $Line -Name $name
                if (-not [string]::IsNullOrWhiteSpace($value) -and
                    $value -notin @('(missing)', '__missing__')) {
                    return $value
                }
            }
            return ''
        }

        function Test-ProofStateVisibleValue {
            param([AllowNull()][string]$Value)

            return -not [string]::IsNullOrWhiteSpace($Value) -and
                $Value -notmatch 'redacted|missing|none'
        }

        function Get-ProofStatePublicationGeneration {
            param([Parameter(Mandatory = $true)]$Event)

            return Get-ProofStateFieldValue `
                -Line $Event.Line `
                -Names @(
                    'publication_generation',
                    'receive_recovery_publication_generation')
        }

        function Get-ProofStateFrameFingerprint {
            param([Parameter(Mandatory = $true)]$Event)

            return Get-ProofStateFieldValue `
                -Line $Event.Line `
                -Names @(
                    'v4_state_wire_fingerprint',
                    'wire_state_fingerprint',
                    'receive_recovery_wire_state_fingerprint',
                    'frame_fingerprint',
                    'receive_recovery_frame_fingerprint')
        }

        function Test-ProofStateOperationMatch {
            param(
                [Parameter(Mandatory = $true)]$Issued,
                [Parameter(Mandatory = $true)]$Candidate
            )

            foreach ($field in @(
                    'log_writer_id',
                    'session_id',
                    'transfer_id',
                    'direction',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'data_session_generation')) {
                $left =
                    Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name $field
                $right =
                    Get-TunaGuiLogLineFieldValue -Line $Candidate.Line -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    $left -ne $right) {
                    return $false
                }
            }

            $leftGeneration = Get-ProofStateFieldValue `
                -Line $Issued.Line `
                -Names @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation')
            $rightGeneration = Get-ProofStateFieldValue `
                -Line $Candidate.Line `
                -Names @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation')
            if ([string]::IsNullOrWhiteSpace($leftGeneration) -or
                $leftGeneration -ne $rightGeneration) {
                return $false
            }

            $leftAuthority = Get-ProofStateFieldValue `
                -Line $Issued.Line `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
            $rightAuthority = Get-ProofStateFieldValue `
                -Line $Candidate.Line `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
            if ((Test-ProofStateVisibleValue $leftAuthority) -and
                (Test-ProofStateVisibleValue $rightAuthority) -and
                $leftAuthority -ne $rightAuthority) {
                return $false
            }
            return $true
        }

        function Test-ProofStateOppositeScopeMatch {
            param(
                [Parameter(Mandatory = $true)]$Publisher,
                [Parameter(Mandatory = $true)]$Target
            )

            if ((Get-TunaGuiLogLineFieldValue `
                        -Line $Publisher.Line `
                        -Name 'direction') -ne 'inbound' -or
                (Get-TunaGuiLogLineFieldValue `
                        -Line $Target.Line `
                        -Name 'direction') -ne 'outbound') {
                return $false
            }

            $publisherWriter =
                Get-TunaGuiLogLineFieldValue `
                    -Line $Publisher.Line `
                    -Name 'log_writer_id'
            $targetWriter =
                Get-TunaGuiLogLineFieldValue `
                    -Line $Target.Line `
                    -Name 'log_writer_id'
            if ([string]::IsNullOrWhiteSpace($publisherWriter) -or
                [string]::IsNullOrWhiteSpace($targetWriter) -or
                $publisherWriter -eq $targetWriter) {
                return $false
            }

            foreach ($field in @(
                    'session_id',
                    'transfer_id',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'data_session_generation')) {
                $left =
                    Get-TunaGuiLogLineFieldValue `
                        -Line $Publisher.Line `
                        -Name $field
                $right =
                    Get-TunaGuiLogLineFieldValue `
                        -Line $Target.Line `
                        -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    $left -ne $right) {
                    return $false
                }
            }
            return $true
        }

        function Test-ProofStatePublicationMatch {
            param(
                [Parameter(Mandatory = $true)]$Issued,
                [Parameter(Mandatory = $true)]$Retained,
                [Parameter(Mandatory = $true)]$Candidate
            )

            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                $left =
                    Get-TunaGuiLogLineFieldValue -Line $Issued.Line -Name $field
                $right =
                    Get-TunaGuiLogLineFieldValue -Line $Candidate.Line -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    $left -ne $right) {
                    return $false
                }
            }

            $issuedGeneration = Get-ProofStateFieldValue `
                -Line $Issued.Line `
                -Names @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation')
            $candidateGeneration = Get-ProofStateFieldValue `
                -Line $Candidate.Line `
                -Names @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation')
            if ([string]::IsNullOrWhiteSpace($issuedGeneration) -or
                $issuedGeneration -ne $candidateGeneration) {
                return $false
            }

            $issuedAuthority = Get-ProofStateFieldValue `
                -Line $Issued.Line `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
            $candidateAuthority = Get-ProofStateFieldValue `
                -Line $Candidate.Line `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
            if ((Test-ProofStateVisibleValue $issuedAuthority) -and
                (Test-ProofStateVisibleValue $candidateAuthority) -and
                $issuedAuthority -ne $candidateAuthority) {
                return $false
            }

            $candidateClosure =
                Get-ProofStateFieldValue `
                    -Line $Candidate.Line `
                    -Names @(
                        'closure_generation',
                        'receive_recovery_closure_generation')
            return [string]::IsNullOrWhiteSpace($candidateClosure) -or
                $candidateClosure -eq
                    (Get-ProofStateFieldValue `
                        -Line $Retained.Line `
                        -Names @('closure_generation'))
        }

        function Test-ProofStatePeerReceiptMatch {
            param(
                [Parameter(Mandatory = $true)]$StateSend,
                [Parameter(Mandatory = $true)]$TargetIssued,
                [Parameter(Mandatory = $true)]$Candidate
            )

            if (-not (Test-TunaGuiLogLineHasEvent `
                        -Line $Candidate.Line `
                        -Events @('filetransfer_v4_state_received')) -or
                (Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'direction') -ne 'outbound') {
                return $false
            }

            foreach ($field in @(
                    'log_writer_id',
                    'session_id',
                    'transfer_id',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'data_session_generation')) {
                $left = Get-TunaGuiLogLineFieldValue `
                    -Line $TargetIssued.Line `
                    -Name $field
                $right = Get-TunaGuiLogLineFieldValue `
                    -Line $Candidate.Line `
                    -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    $left -ne $right) {
                    return $false
                }
            }

            $sentEpoch =
                Get-TunaGuiLogLineFieldValue -Line $StateSend.Line -Name 'epoch'
            $receivedEpoch =
                Get-TunaGuiLogLineFieldValue -Line $Candidate.Line -Name 'epoch'
            if ([string]::IsNullOrWhiteSpace($sentEpoch) -or
                $sentEpoch -ne $receivedEpoch) {
                return $false
            }

            $sentFingerprint =
                Get-ProofStateFrameFingerprint -Event $StateSend
            $receivedFingerprint =
                Get-ProofStateFrameFingerprint -Event $Candidate
            if ((Test-ProofStateVisibleValue $sentFingerprint) -or
                (Test-ProofStateVisibleValue $receivedFingerprint)) {
                return (Test-ProofStateVisibleValue $sentFingerprint) -and
                    (Test-ProofStateVisibleValue $receivedFingerprint) -and
                    $sentFingerprint -eq $receivedFingerprint
            }
            return $true
        }

        function Select-ProofStatePeerReceipt {
            param([Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Candidates)

            if ($Candidates.Count -eq 0) {
                return @()
            }

            $identityKeys = @($Candidates | ForEach-Object {
                $fingerprint = Get-ProofStateFrameFingerprint -Event $_
                if (-not (Test-ProofStateVisibleValue $fingerprint)) {
                    return ''
                }

                return [string]::Join('|', @(
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'protocol_version'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'live_route_epoch'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route_publication_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'runtime_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'terminal_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'leg_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transport_epoch'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'bridge_recovery_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'data_session_generation'),
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'epoch'),
                    $fingerprint)).ToLowerInvariant()
            } | Select-Object -Unique)

            if ($Candidates.Count -gt 1 -and
                ($identityKeys.Count -ne 1 -or
                    [string]::IsNullOrWhiteSpace([string]$identityKeys[0]))) {
                return @()
            }

            $applied = @($Candidates | Where-Object {
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'applied') -eq '1'
            } | Sort-Object Index | Select-Object -First 1)
            if ($applied.Count -eq 1) {
                return $applied
            }

            return @($Candidates | Sort-Object Index | Select-Object -First 1)
        }

        function Test-ProofStatePayloadAdmissionMatch {
            param(
                [Parameter(Mandatory = $true)]$Operation,
                [Parameter(Mandatory = $true)]$Candidate
            )

            foreach ($mapping in @(
                    @('session_id', 'session_id'),
                    @('transfer_id', 'transfer_id'),
                    @('direction', 'direction'),
                    @('route', 'source_route'),
                    @('protocol_version', 'source_protocol_version'),
                    @('live_route_epoch', 'source_live_route_epoch'),
                    @('route_publication_generation', 'source_route_publication_generation'),
                    @('runtime_generation', 'source_runtime_generation'),
                    @('terminal_generation', 'source_terminal_generation'),
                    @('leg_generation', 'source_leg_generation'),
                    @('transport_epoch', 'source_transport_epoch'),
                    @('bridge_recovery_generation', 'source_bridge_recovery_generation'),
                    @('data_session_generation', 'source_data_session_generation'))) {
                $left = Get-ProofStateFieldValue -Line $Operation.Line -Names @($mapping[0])
                $right = Get-ProofStateFieldValue -Line $Candidate.Line -Names @($mapping[1])
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    -not [string]::Equals(
                        $left,
                        $right,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }

            return (Get-ProofStateFieldValue -Line $Candidate.Line -Names @('send_kind')) -in @(
                'RegularV4Payload',
                'RegularV4Repair')
        }

        function Test-ProofStateHeartbeatPair {
            param(
                [Parameter(Mandatory = $true)]$Heartbeat,
                [Parameter(Mandatory = $true)]$Proof,
                [Parameter(Mandatory = $true)]$Publisher
            )

            if (-not (Test-TunaGuiLogLineHasEvent `
                        -Line $Heartbeat.Line `
                        -Events @('session_liveness_heartbeat_received')) -or
                -not (Test-TunaGuiLogLineHasEvent `
                        -Line $Proof.Line `
                        -Events @('session_liveness_proof_received')) -or
                (Get-TunaGuiLogLineFieldValue `
                        -Line $Proof.Line `
                        -Name 'proof_kind') -ne 'heartbeat_received' -or
                $Proof.Index -le $Heartbeat.Index) {
                return $false
            }

            foreach ($event in @($Heartbeat, $Proof)) {
                if ((Get-TunaGuiLogLineFieldValue `
                            -Line $event.Line `
                            -Name 'log_writer_id') -ne
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $Publisher.Line `
                            -Name 'log_writer_id') -or
                    (Get-TunaGuiLogLineFieldValue `
                            -Line $event.Line `
                            -Name 'session_id') -ne
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $Publisher.Line `
                            -Name 'session_id')) {
                    return $false
                }
            }

            foreach ($field in @('generation', 'sequence', 'lane')) {
                $left =
                    Get-TunaGuiLogLineFieldValue `
                        -Line $Heartbeat.Line `
                        -Name $field
                $right =
                    Get-TunaGuiLogLineFieldValue `
                        -Line $Proof.Line `
                        -Name $field
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    $left -ne $right) {
                    return $false
                }
            }
            return $true
        }

        $issuedEvents = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_receive_recovery_operation_issued')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                'inbound' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route') -eq
                'regular_nkn_v4_fast'
        })

        # A proof-state command observed while the exact regular-V4 Tuna
        # activation barrier is active must remain Held until that barrier is
        # released.  This path does not require another bridge-ready event
        # because a successor recovery may reuse the ready process.
        foreach ($issued in $issuedEvents) {
            $retained = @($indexedLines | Where-Object {
                $_.Index -gt $issued.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_retained')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Retained' -and
                (Test-ProofStateOperationMatch `
                    -Issued $issued `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($retained.Count -ne 1) {
                continue
            }

            $decision = @($indexedLines | Where-Object {
                $_.Index -gt $retained[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_decided')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Started',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($decision.Count -ne 1) {
                continue
            }

            $disposition = @($indexedLines | Where-Object {
                $_.Index -gt $decision[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'publication_outcome') -in @('Held', 'Rejected') -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @('Accepted', 'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($disposition.Count -ne 1) {
                continue
            }

            $outcome = Get-TunaGuiLogLineFieldValue `
                -Line $disposition[0].Line `
                -Name 'publication_outcome'
            $reason = Get-ProofStateFieldValue `
                -Line $disposition[0].Line `
                -Names @('publication_reason', 'reason')
            if (($outcome -eq 'Rejected' -and
                 $reason -ne
                    'filetransfer_receive_recovery_proof_state_not_sent') -or
                ($outcome -eq 'Held' -and
                 $reason -ne
                    'filetransfer_receive_recovery_proof_state_held_for_tuna_activation_pause')) {
                continue
            }

            $writer = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'transfer_id'
            $pause = @($indexedLines | Where-Object {
                $_.Index -lt $disposition[0].Index -and
                (
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_tuna_activation_transport_pause_control_suppressed')) -and
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'paused') -eq '1'
                    ) -or
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_transport_paused'))
                ) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'reason') -eq 'tuna_activation_negotiating' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'direction') -eq 'inbound'
            } | Select-Object -Last 1)
            if ($pause.Count -ne 1) {
                continue
            }

            $releasedBeforeDisposition = @($indexedLines | Where-Object {
                $_.Index -gt $pause[0].Index -and
                $_.Index -le $disposition[0].Index -and
                (
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @(
                            'filetransfer_tuna_activation_local_barrier_released',
                            'filetransfer_transport_resumed')) -or
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_tuna_activation_transport_pause_control_suppressed')) -and
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'paused') -eq '0'
                    )
                ) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'transfer_id') -eq $transfer
            }).Count -gt 0
            $attemptedBeforeDisposition = @($indexedLines | Where-Object {
                $_.Index -gt $decision[0].Index -and
                $_.Index -le $disposition[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_attempted',
                        'filetransfer_v4_state_sent')) -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            }).Count -gt 0
            if ($releasedBeforeDisposition -or $attemptedBeforeDisposition) {
                continue
            }

            $resume = @($indexedLines | Where-Object {
                $_.Index -gt $disposition[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_resume_decided')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Started',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            $stateSend = @($indexedLines | Where-Object {
                $resume.Count -eq 1 -and
                $_.Index -gt $resume[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_v4_state_sent')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'repair_publication_kind') -eq
                        'receive_recovery_proof_state' -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            $delivered = @($indexedLines | Where-Object {
                $stateSend.Count -eq 1 -and
                $_.Index -gt $stateSend[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'publication_outcome') -eq 'Delivered' -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            $peerReceipt = @($indexedLines | Where-Object {
                $stateSend.Count -eq 1 -and
                $_.Index -gt $stateSend[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_v4_state_received')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'direction') -eq 'outbound' -and
                (Get-ProofStateFrameFingerprint -Event $_) -eq
                    (Get-ProofStateFrameFingerprint -Event $stateSend[0])
            } | Select-Object -First 1)
            $adopted = @($indexedLines | Where-Object {
                $peerReceipt.Count -eq 1 -and
                $_.Index -gt $peerReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_adopted')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'direction') -eq 'outbound'
            } | Select-Object -First 1)
            $resumed = @($indexedLines | Where-Object {
                $adopted.Count -eq 1 -and
                $_.Index -gt $adopted[0].Index -and
                (
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_bridge_recovery_payload_submission_resumed')) -and
                        (Test-ProofStateOperationMatch `
                            -Issued $adopted[0] `
                            -Candidate $_)
                    ) -or
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_regular_v4_physical_send_lease_registered',
                                'filetransfer_route_transition_physical_send_lease_registered')) -and
                        (Test-ProofStatePayloadAdmissionMatch `
                            -Operation $adopted[0] `
                            -Candidate $_)
                    )
                )
            } | Select-Object -First 2)
            if ($resume.Count -eq 1 -and
                $stateSend.Count -eq 1 -and
                $delivered.Count -eq 1 -and
                $peerReceipt.Count -eq 1 -and
                $adopted.Count -eq 1 -and
                $resumed.Count -eq 1) {
                continue
            }

            $successorInvalidation = @($indexedLines | Where-Object {
                $_.Index -gt $disposition[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_invalidated')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'invalidation_target') -eq 'pending_command' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_reason') -eq
                        'filetransfer_receive_recovery_operation_successor_issued' -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($successorInvalidation.Count -eq 1) {
                continue
            }

            return $true
        }

        foreach ($issued in $issuedEvents) {
            $writer = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'log_writer_id'
            $operationGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'receive_recovery_operation_generation'
            $bridgeDecisionGeneration = Get-TunaGuiLogLineFieldValue `
                -Line $issued.Line `
                -Name 'bridge_decision_generation'

            $retained = @($indexedLines | Where-Object {
                $_.Index -gt $issued.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_retained')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'receive_recovery_operation_generation') -eq
                    $operationGeneration -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Retained'
            } | Select-Object -First 1)
            if ($retained.Count -ne 1) {
                continue
            }

            $diagnostic = @($indexedLines | Where-Object {
                $_.Index -gt $retained[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_bridge_recovery_lifecycle_diagnostic_only')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'bridge_decision_generation') -eq
                    $bridgeDecisionGeneration -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'lifecycle').ToLowerInvariant() -eq
                    'receivestallrecoveryreceiveresumed' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'reason') -eq
                    'coordinator_operation_receipt_or_proof_required'
            } | Select-Object -First 1)
            if ($diagnostic.Count -ne 1) {
                continue
            }

            $resolved = @($indexedLines | Where-Object {
                $_.Index -gt $diagnostic[0].Index -and
                (
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_proof_state_publication_decided')) -and
                        (Get-ProofStateFieldValue `
                            -Line $_.Line `
                            -Names @(
                                'receive_recovery_operation_generation',
                                'recovery_operation_generation')) -eq
                            $operationGeneration
                    ) -or
                    (
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_operation_proof_observed',
                                'filetransfer_receive_recovery_operation_closure_adopted')) -and
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'log_writer_id') -eq $writer -and
                        (Get-ProofStateFieldValue `
                            -Line $_.Line `
                            -Names @(
                                'receive_recovery_operation_generation',
                                'recovery_operation_generation')) -eq
                            $operationGeneration
                    )
                )
            } | Select-Object -First 1)
            if ($resolved.Count -eq 0) {
                return $true
            }
        }

        # Detect the arrival-order hole where a proof-state frame was submitted
        # before the opposite recovery process became reachable.  The
        # Core-facing heartbeat proof is the first publisher-visible recheck
        # boundary; the raw heartbeat must carry the same immutable identity.
        foreach ($issued in $issuedEvents) {
            $retained = @($indexedLines | Where-Object {
                $_.Index -gt $issued.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_retained')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Retained' -and
                (Test-ProofStateOperationMatch `
                    -Issued $issued `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($retained.Count -ne 1) {
                continue
            }

            $publicationDecision = @($indexedLines | Where-Object {
                $_.Index -gt $retained[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_decided')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Started',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            $stateSend = @($indexedLines | Where-Object {
                $publicationDecision.Count -eq 1 -and
                $_.Index -gt $publicationDecision[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_v4_state_sent')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'repair_publication_kind') -eq
                        'receive_recovery_proof_state' -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            $publicationReceipt = @($indexedLines | Where-Object {
                $stateSend.Count -eq 1 -and
                $_.Index -gt $stateSend[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'publication_outcome') -eq 'Delivered' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($publicationReceipt.Count -ne 1) {
                continue
            }
            if ((Get-ProofStatePublicationGeneration `
                    -Event $publicationDecision[0]) -ne '1' -or
                (Get-ProofStatePublicationGeneration -Event $stateSend[0]) -ne
                    '1' -or
                (Get-ProofStatePublicationGeneration `
                    -Event $publicationReceipt[0]) -ne '1') {
                continue
            }

            $targetBoundaries = @()
            foreach ($targetIssued in @($indexedLines | Where-Object {
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_operation_issued')) -and
                        (Test-ProofStateOppositeScopeMatch `
                            -Publisher $issued `
                            -Target $_)
                    })) {
                $targetReceipt = @($indexedLines | Where-Object {
                    $_.Index -gt $publicationReceipt[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @(
                            'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'execution_outcome') -eq 'Completed' -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'closure_state') -eq 'Retained' -and
                    (Test-ProofStateOperationMatch `
                        -Issued $targetIssued `
                        -Candidate $_)
                } | Select-Object -First 1)
                $targetRetained = @($indexedLines | Where-Object {
                    $targetReceipt.Count -eq 1 -and
                    $_.Index -ge $targetReceipt[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @(
                            'filetransfer_receive_recovery_operation_closure_retained')) -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'closure_state') -eq 'Retained' -and
                    (Test-ProofStateOperationMatch `
                        -Issued $targetIssued `
                        -Candidate $_)
                } | Select-Object -First 1)
                if ($targetRetained.Count -ne 1) {
                    continue
                }

                $terminalIndex = [int]::MaxValue
                $operationInvalidation = @($indexedLines | Where-Object {
                    $_.Index -gt $targetRetained[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_receive_recovery_operation_invalidated')) -and
                    (Test-ProofStateOperationMatch -Issued $issued -Candidate $_)
                } | Select-Object -First 1)
                if ($operationInvalidation.Count -eq 1) {
                    $terminalIndex = [Math]::Min(
                        $terminalIndex,
                        [int]$operationInvalidation[0].Index)
                }
                $transferTerminal = @($indexedLines | Where-Object {
                    $_.Index -gt $targetRetained[0].Index -and
                    (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @(
                            'transfer_terminal',
                            'file_transfer_inbound_terminal',
                            'file_transfer_outbound_terminal',
                            'filetransfer_runtime_terminalized')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                        (Get-TunaGuiLogLineFieldValue -Line $issued.Line -Name 'log_writer_id') -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                        (Get-TunaGuiLogLineFieldValue -Line $issued.Line -Name 'session_id') -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                        (Get-TunaGuiLogLineFieldValue -Line $issued.Line -Name 'transfer_id')
                } | Select-Object -First 1)
                if ($transferTerminal.Count -eq 1) {
                    $terminalIndex = [Math]::Min(
                        $terminalIndex,
                        [int]$transferTerminal[0].Index)
                }
                $heartbeatPair = $null
                foreach ($proof in @($indexedLines | Where-Object {
                            $_.Index -gt $targetRetained[0].Index -and
                            $_.Index -lt $terminalIndex -and
                            (Test-TunaGuiLogLineHasEvent `
                                -Line $_.Line `
                                -Events @(
                                    'session_liveness_proof_received')) -and
                            (Get-TunaGuiLogLineFieldValue `
                                -Line $_.Line `
                                -Name 'proof_kind') -eq
                                    'heartbeat_received'
                        })) {
                    $heartbeat = @($indexedLines | Where-Object {
                        $_.Index -gt $targetRetained[0].Index -and
                        $_.Index -lt $proof.Index -and
                        (Test-ProofStateHeartbeatPair `
                            -Heartbeat $_ `
                            -Proof $proof `
                            -Publisher $issued)
                    } | Select-Object -Last 1)
                    if ($heartbeat.Count -eq 1) {
                        $heartbeatPair = [pscustomobject]@{
                            Heartbeat = $heartbeat[0]
                            Proof = $proof
                        }
                        break
                    }
                }
                if ($null -ne $heartbeatPair) {
                    $naturalProof = @($indexedLines | Where-Object {
                        $_.Index -gt $publicationReceipt[0].Index -and
                        $_.Index -le $heartbeatPair.Proof.Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_operation_proof_observed',
                                'filetransfer_receive_recovery_operation_receive_proof_observed',
                                'filetransfer_receive_recovery_operation_closure_adopted')) -and
                        (
                            (Test-ProofStateOperationMatch `
                                -Issued $issued `
                                -Candidate $_) -or
                            (Test-ProofStateOperationMatch `
                                -Issued $targetIssued `
                                -Candidate $_)
                        )
                    })
                    $postReadyReceipt = @($indexedLines | Where-Object {
                        $_.Index -gt $targetRetained[0].Index -and
                        $_.Index -le $heartbeatPair.Proof.Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                        (Test-ProofStatePublicationMatch `
                            -Issued $issued `
                            -Retained $retained[0] `
                            -Candidate $_)
                    })
                    if ($naturalProof.Count -gt 0 -or
                        $postReadyReceipt.Count -gt 0) {
                        continue
                    }

                    $targetBoundaries += [pscustomobject]@{
                        Issued = $targetIssued
                        Retained = $targetRetained[0]
                        HeartbeatPair = $heartbeatPair
                    }
                }
            }
            if ($targetBoundaries.Count -ne 1) {
                continue
            }

            $boundary = $targetBoundaries[0].HeartbeatPair.Proof
            $initialFingerprint =
                Get-ProofStateFrameFingerprint -Event $publicationReceipt[0]
            $recheck = @($indexedLines | Where-Object {
                $_.Index -gt $boundary.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_recheck_decided')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Started',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_) -and
                (Get-ProofStatePublicationGeneration -Event $_) -eq '2' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'predecessor_publication_generation') -eq '1' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'heartbeat_generation') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $boundary.Line `
                        -Name 'generation') -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'heartbeat_sequence') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $boundary.Line `
                        -Name 'sequence') -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'proof_kind') -eq 'heartbeat_received' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'lane') -eq
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $boundary.Line `
                        -Name 'lane')
            } | Select-Object -First 1)
            $recheckSend = @($indexedLines | Where-Object {
                $recheck.Count -eq 1 -and
                $_.Index -gt $recheck[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_v4_state_sent')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'repair_publication_kind') -eq
                        'receive_recovery_proof_state' -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_) -and
                (Get-ProofStatePublicationGeneration -Event $_) -eq '2' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'receive_recovery_publication_attempt') -eq
                        'post_delivery_recheck' -and
                (Get-ProofStateFieldValue `
                    -Line $_.Line `
                    -Names @(
                        'receive_recovery_predecessor_publication_generation',
                        'predecessor_publication_generation')) -eq '1'
            } | Select-Object -First 1)
            $recheckReceipt = @($indexedLines | Where-Object {
                $recheckSend.Count -eq 1 -and
                $_.Index -gt $recheckSend[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'publication_outcome') -eq 'Delivered' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Accepted',
                        'Idempotent') -and
                (Test-ProofStatePublicationMatch `
                    -Issued $issued `
                    -Retained $retained[0] `
                    -Candidate $_) -and
                (Get-ProofStatePublicationGeneration -Event $_) -eq '2' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'publication_attempt') -eq
                        'post_delivery_recheck' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'predecessor_publication_generation') -eq '1'
            } | Select-Object -First 1)
            $predecessorFingerprintMatch =
                -not (Test-ProofStateVisibleValue $initialFingerprint) -or
                (
                    $recheck.Count -eq 1 -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $recheck[0].Line `
                        -Name 'predecessor_frame_fingerprint') -eq
                            $initialFingerprint
                )
            $recheckSendFingerprint = if ($recheckSend.Count -eq 1) {
                Get-ProofStateFrameFingerprint -Event $recheckSend[0]
            }
            else {
                ''
            }
            $recheckReceiptFingerprint = if ($recheckReceipt.Count -eq 1) {
                Get-ProofStateFrameFingerprint -Event $recheckReceipt[0]
            }
            else {
                ''
            }
            $recheckFingerprintMatch =
                (Test-ProofStateVisibleValue $recheckSendFingerprint) -and
                (Test-ProofStateVisibleValue $recheckReceiptFingerprint) -and
                $recheckSendFingerprint -eq $recheckReceiptFingerprint
            $peerReceiptCandidates = @($indexedLines | Where-Object {
                $recheckReceipt.Count -eq 1 -and
                $_.Index -gt $recheckReceipt[0].Index -and
                (Test-ProofStatePeerReceiptMatch `
                    -StateSend $recheckSend[0] `
                    -TargetIssued $targetBoundaries[0].Issued `
                    -Candidate $_)
            })
            $peerReceipt = @(Select-ProofStatePeerReceipt `
                -Candidates $peerReceiptCandidates)
            $targetProof = @($indexedLines | Where-Object {
                $peerReceipt.Count -eq 1 -and
                $_.Index -gt $peerReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_proof_observed',
                        'filetransfer_receive_recovery_operation_receive_proof_observed')) -and
                (Test-ProofStateOperationMatch `
                    -Issued $targetBoundaries[0].Issued `
                    -Candidate $_)
            } | Select-Object -First 1)
            $targetAdopted = @($indexedLines | Where-Object {
                $targetProof.Count -eq 1 -and
                $_.Index -gt $targetProof[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_closure_adopted')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'closure_state') -eq 'Adopted' -and
                (Test-ProofStateOperationMatch `
                    -Issued $targetBoundaries[0].Issued `
                    -Candidate $_)
            } | Select-Object -First 1)
            $payloadResume = @($indexedLines | Where-Object {
                $targetAdopted.Count -eq 1 -and
                (
                    (
                        $_.Index -gt $targetAdopted[0].Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_bridge_recovery_payload_submission_resumed')) -and
                        (Test-ProofStateOperationMatch `
                            -Issued $targetBoundaries[0].Issued `
                            -Candidate $_)
                    ) -or
                    (
                        $recheckReceipt.Count -eq 1 -and
                        $_.Index -gt $recheckReceipt[0].Index -and
                        $_.Index -le $targetAdopted[0].Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_receive_recovery_proof_state_publication_recheck_invalidated')) -and
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'invalidation_target') -eq 'recheck_arm' -and
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'decision_reason') -eq 'receive_recovery_proof_observed' -and
                        (Test-ProofStatePublicationMatch `
                            -Issued $issued `
                            -Retained $retained[0] `
                            -Candidate $_)
                    ) -or
                    (
                        $_.Index -gt $targetAdopted[0].Index -and
                        (Test-TunaGuiLogLineHasEvent `
                            -Line $_.Line `
                            -Events @(
                                'filetransfer_regular_v4_physical_send_lease_registered',
                                'filetransfer_route_transition_physical_send_lease_registered')) -and
                        (Test-ProofStatePayloadAdmissionMatch `
                            -Operation $targetBoundaries[0].Issued `
                            -Candidate $_)
                    )
                )
            } | Select-Object -First 2)
            if ($recheckReceipt.Count -ne 1 -or
                -not $predecessorFingerprintMatch -or
                -not $recheckFingerprintMatch -or
                $peerReceipt.Count -ne 1 -or
                $targetProof.Count -ne 1 -or
                $targetAdopted.Count -ne 1 -or
                $payloadResume.Count -ne 1) {
                return $true
            }
        }
        return $false
    }

    function Test-TunaGuiReceiveRecoveryProofStateRecheckHeartbeatSuppressionFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $arms = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_receive_recovery_proof_state_publication_recheck_armed')) -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'inbound' -and
            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_publication_generation') -eq '1'
        })
        foreach ($arm in $arms) {
            $session = Get-TunaGuiLogLineFieldValue -Line $arm.Line -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue -Line $arm.Line -Name 'transfer_id'
            $outboundRetained = @($indexedLines | Where-Object {
                $_.Index -gt $arm.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_closure_retained')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'route') -eq 'regular_nkn_v4_fast' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq 'Retained'
            } | Select-Object -First 1)
            if ($outboundRetained.Count -ne 1) {
                continue
            }

            $outboundWriter = Get-TunaGuiLogLineFieldValue -Line $outboundRetained[0].Line -Name 'log_writer_id'
            $endIndex = [int]::MaxValue
            $terminal = @($indexedLines | Where-Object {
                $_.Index -gt $outboundRetained[0].Index -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_receive_recovery_operation_invalidated',
                        'transfer_terminal',
                        'file_transfer_outbound_terminal',
                        'filetransfer_runtime_terminalized'))
            } | Select-Object -First 1)
            if ($terminal.Count -eq 1) {
                $endIndex = $terminal[0].Index
            }
            $proofBoundary = @($indexedLines | Where-Object {
                $_.Index -gt $outboundRetained[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_proof_observed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound'
            } | Select-Object -First 1)
            if ($proofBoundary.Count -eq 1) {
                $endIndex = [Math]::Min($endIndex, $proofBoundary[0].Index)
            }

            $skip = @($indexedLines | Where-Object {
                $_.Index -gt $outboundRetained[0].Index -and
                $_.Index -lt $endIndex -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('session_liveness_heartbeat_skipped_for_active_filetransfer_progress')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound'
            } | Select-Object -First 1)
            if ($skip.Count -ne 1) {
                continue
            }

            $required = @($indexedLines | Where-Object {
                $_.Index -ge $skip[0].Index -and
                $_.Index -lt $endIndex -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('session_liveness_heartbeat_required_for_receive_recovery_proof_state_recheck')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter
            } | Select-Object -First 1)
            $heartbeatSent = @($indexedLines | Where-Object {
                $required.Count -eq 1 -and
                $_.Index -gt $required[0].Index -and
                $_.Index -lt $endIndex -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('session_liveness_heartbeat_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session
            } | Select-Object -First 1)
            $publisherWriter = Get-TunaGuiLogLineFieldValue -Line $arm.Line -Name 'log_writer_id'
            $heartbeatReceived = @($indexedLines | Where-Object {
                $heartbeatSent.Count -eq 1 -and
                $_.Index -gt $heartbeatSent[0].Index -and
                $_.Index -lt $endIndex -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('session_liveness_heartbeat_received')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $publisherWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session
            } | Select-Object -First 1)
            $recheck = @($indexedLines | Where-Object {
                $heartbeatReceived.Count -eq 1 -and
                $_.Index -gt $heartbeatReceived[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_proof_state_publication_recheck_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'publication_generation') -eq '2' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -in @('Accepted', 'Idempotent', 'Started')
            } | Select-Object -First 1)
            $stateSent = @($indexedLines | Where-Object {
                $recheck.Count -eq 1 -and
                $_.Index -gt $recheck[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_v4_state_sent')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $publisherWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'publication_generation') -eq '2' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_publication_kind') -eq 'receive_recovery_proof_state'
            } | Select-Object -First 1)
            $stateReceipt = @($indexedLines | Where-Object {
                $stateSent.Count -eq 1 -and
                $_.Index -gt $stateSent[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_proof_state_publication_receipt_applied')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $publisherWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'publication_generation') -eq '2' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'publication_outcome') -eq 'Delivered'
            } | Select-Object -First 1)
            $peerReceipt = @($indexedLines | Where-Object {
                $stateReceipt.Count -eq 1 -and
                $_.Index -gt $stateReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_v4_state_received')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer
            } | Select-Object -First 1)
            $proof = @($indexedLines | Where-Object {
                $peerReceipt.Count -eq 1 -and
                $_.Index -gt $peerReceipt[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_proof_observed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq $outboundWriter -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound'
            } | Select-Object -First 1)
            $adopted = @($indexedLines | Where-Object {
                $proof.Count -eq 1 -and
                $_.Index -gt $proof[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_receive_recovery_operation_closure_adopted')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq 'Adopted'
            } | Select-Object -First 1)
            $resumed = @($indexedLines | Where-Object {
                $adopted.Count -eq 1 -and
                $_.Index -gt $adopted[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_bridge_recovery_payload_submission_resumed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq 'outbound'
            } | Select-Object -First 2)
            if ($required.Count -ne 1 -or
                $heartbeatSent.Count -ne 1 -or
                $heartbeatReceived.Count -ne 1 -or
                $recheck.Count -ne 1 -or
                $stateSent.Count -ne 1 -or
                $stateReceipt.Count -ne 1 -or
                $peerReceipt.Count -ne 1 -or
                $proof.Count -ne 1 -or
                $adopted.Count -ne 1 -or
                $resumed.Count -ne 1) {
                return $true
            }
        }
        return $false
    }

    function Test-TunaGuiBridgeRecoveryExecutionSubmissionBarrierDrainFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )

        function Test-TunaGuiBridgeRecoveryDrainScope {
            param(
                [Parameter(Mandatory = $true)][string]$CommandLine,
                [Parameter(Mandatory = $true)][string]$CandidateLine,
                [switch]$SourcePrefixed,
                [switch]$RequireWriter
            )

            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                if (-not (Test-TunaGuiLogLineFieldMatch `
                        -SourceLine $CommandLine `
                        -CandidateLine $CandidateLine `
                        -FieldName $field)) {
                    return $false
                }
            }

            $commandRoute = (
                Get-TunaGuiLogLineFieldValue -Line $CommandLine -Name 'route'
            ).ToLowerInvariant() -replace '[^a-z0-9]', ''
            $candidateRouteField = if ($SourcePrefixed) { 'source_route' } else { 'route' }
            $candidateRoute = (
                Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $candidateRouteField
            ).ToLowerInvariant() -replace '[^a-z0-9]', ''
            if ([string]::IsNullOrWhiteSpace($commandRoute) -or
                $commandRoute -ne $candidateRoute) {
                return $false
            }

            foreach ($field in @(
                    'protocol_version',
                    'live_route_epoch',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation')) {
                $expected = Get-TunaGuiLogLineFieldValue -Line $CommandLine -Name $field
                $candidateField = if ($SourcePrefixed) { "source_$field" } else { $field }
                $actual = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $candidateField
                if ([string]::IsNullOrWhiteSpace($expected) -or
                    [string]::IsNullOrWhiteSpace($actual) -or
                    $expected -ne $actual) {
                    return $false
                }
            }

            if (-not $SourcePrefixed -and
                -not (Test-TunaGuiLogLineFieldMatch `
                    -SourceLine $CommandLine `
                    -CandidateLine $CandidateLine `
                    -FieldName 'bridge_decision_generation')) {
                return $false
            }

            if ($RequireWriter) {
                $commandWriter =
                    Get-TunaGuiLogLineFieldValue -Line $CommandLine -Name 'log_writer_id'
                $candidateWriter =
                    Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name 'log_writer_id'
                if ([string]::IsNullOrWhiteSpace($commandWriter) -or
                    $commandWriter -ne $candidateWriter) {
                    return $false
                }
            }

            return $true
        }

        $commands = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_bridge_recovery_execution_command_issued')
        })
        foreach ($command in $commands) {
            $leaseGeneration =
                Get-TunaGuiLogLineFieldValue `
                    -Line $command.Line `
                    -Name 'recovery_liveness_lease_generation'
            if ([string]::IsNullOrWhiteSpace($leaseGeneration) -or $leaseGeneration -eq '0') {
                continue
            }

            $start = @($indexedLines | Where-Object {
                $_.Index -gt $command.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_execution_started')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($start.Count -eq 0) {
                continue
            }

            $barrier = @($indexedLines | Where-Object {
                $_.Index -gt $start[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_submission_barrier_closed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($barrier.Count -eq 0) {
                continue
            }

            $submissionEpoch =
                Get-TunaGuiLogLineFieldValue -Line $barrier[0].Line -Name 'submission_epoch'
            $sourceProcessEpoch =
                Get-TunaGuiLogLineFieldValue -Line $barrier[0].Line -Name 'source_process_epoch'
            $sourceProcessId =
                Get-TunaGuiLogLineFieldValue -Line $barrier[0].Line -Name 'source_process_id'
            if ([string]::IsNullOrWhiteSpace($submissionEpoch) -or
                $submissionEpoch -eq '0' -or
                [string]::IsNullOrWhiteSpace($sourceProcessEpoch) -or
                [string]::IsNullOrWhiteSpace($sourceProcessId)) {
                continue
            }

            $held = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_bridge_recovery_payload_submission_held')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_execution_state') -in
                    @('Issued', 'Running') -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'recovery_liveness_lease_generation') -eq $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line)
            } | Select-Object -First 1)
            if ($held.Count -eq 0) {
                continue
            }

            $fullyRetired = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_outbound_physical_send_lease_retired',
                    'filetransfer_route_transition_physical_send_lease_retired')) -and
                [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'registered_send_count') -gt 0 -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'registered_send_count') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retired_send_count') -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -SourcePrefixed `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($fullyRetired.Count -eq 0) {
                continue
            }

            $invalidation = @($indexedLines | Where-Object {
                $_.Index -gt $fullyRetired[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_submission_barrier_invalidated')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                    'bridge_recovery_execution_restart_not_ready' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    $leaseGeneration -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'submission_epoch') -eq
                    $submissionEpoch -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_process_epoch') -eq
                    $sourceProcessEpoch -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_process_id') -eq
                    $sourceProcessId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'process_epoch') -eq
                    $sourceProcessEpoch -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'process_id') -eq
                    $sourceProcessId -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($invalidation.Count -eq 0) {
                continue
            }

            $hardDecision = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                $_.Index -lt $invalidation[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_execution_hard_restart_decided')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Started' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            })
            $spawnOrReady = @($indexedLines | Where-Object {
                $_.Index -gt $barrier[0].Index -and
                $_.Index -lt $invalidation[0].Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('bridge_spawned', 'bridge_ready')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                    (Get-TunaGuiLogLineFieldValue -Line $command.Line -Name 'log_writer_id')
            })
            if ($hardDecision.Count -gt 0 -or $spawnOrReady.Count -gt 0) {
                continue
            }

            $completion = @($indexedLines | Where-Object {
                $_.Index -gt $invalidation[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('nkn_bridge_recovery_execution_completed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'outcome') -eq 'exhausted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq
                    'bridge_recovery_execution_timeout' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'physical_execution_terminated') -eq '1' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'total_deadline_expired') -eq '1' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lease_generation') -eq
                    $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($completion.Count -eq 0) {
                continue
            }

            $receipt = @($indexedLines | Where-Object {
                $_.Index -gt $completion[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_bridge_recovery_execution_receipt_decision_observed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'accepted') -eq '1' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'disposition') -eq 'accepted' -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq
                    'exhausted' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'recovery_liveness_lease_generation') -eq $leaseGeneration -and
                (Test-TunaGuiBridgeRecoveryDrainScope `
                    -CommandLine $command.Line `
                    -CandidateLine $_.Line `
                    -RequireWriter)
            } | Select-Object -First 1)
            if ($receipt.Count -gt 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiRegularV4FrontierRepairSettlementClosed {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines,
            [switch]$RequireRecoveryProof,
            [AllowNull()]$Metrics = $null
        )

        $eventIndex =
            [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new(
                [System.StringComparer]::OrdinalIgnoreCase)
        $identityIndex =
            [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]::new(
                [System.StringComparer]::OrdinalIgnoreCase)
        $seenWriterRecords =
            [System.Collections.Generic.HashSet[string]]::new(
                [System.StringComparer]::Ordinal)
        $relevantEvents =
            [System.Collections.Generic.HashSet[string]]::new(
                [string[]]@(
                    'filetransfer_regular_v4_frontier_repair_settlement_accepted',
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_committed',
                    'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided',
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_retired',
                    'filetransfer_regular_v4_frontier_repair_contract_settled',
                    'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_prepared',
                    'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed',
                    'filetransfer_receive_recovery_operation_issued',
                    'filetransfer_receive_recovery_operation_execution_receipt_applied',
                    'filetransfer_receive_recovery_operation_proof_observed',
                    'filetransfer_receive_recovery_operation_closure_adopted',
                    'runtime_unlock_regular_v4_frontier_repair_settlement_released',
                    'runtime_unlock_regular_v4_frontier_repair_settlement_held',
                    'runtime_unlock_regular_v4_frontier_repair_settlement_rejected',
                    'runtime_unlock_regular_v4_frontier_repair_precontract_settlement_consumed',
                    'regular_v4_receive_recovery_contract_closed_no_deferral'),
                [System.StringComparer]::OrdinalIgnoreCase)
        function Add-TunaGuiSettlementIndexRecord {
            param(
                [Parameter(Mandatory = $true)]
                [System.Collections.Generic.Dictionary[string, System.Collections.Generic.List[object]]]$Index,
                [Parameter(Mandatory = $true)][string]$Key,
                [Parameter(Mandatory = $true)]$Record
            )

            if ([string]::IsNullOrWhiteSpace($Key)) {
                return
            }
            $bucket = $null
            if (-not $Index.TryGetValue($Key, [ref]$bucket)) {
                $bucket = [System.Collections.Generic.List[object]]::new()
                $Index.Add($Key, $bucket)
            }
            $bucket.Add($Record)
        }

        function Get-TunaGuiSettlementIdentityKey {
            param(
                [Parameter(Mandatory = $true)][string]$Event,
                [AllowEmptyString()][string]$Authority = '',
                [AllowEmptyString()][string]$InstallGeneration = '',
                [AllowEmptyString()][string]$RepairKey = ''
            )

            return [string]::Join(
                [char]0x1f,
                @(
                    $Event.ToLowerInvariant(),
                    $Authority.ToLowerInvariant(),
                    $InstallGeneration.ToLowerInvariant(),
                    $RepairKey.ToLowerInvariant()))
        }

        for ($i = 0; $i -lt $Lines.Count; $i++) {
            $line = [string]$Lines[$i]
            $fields =
                [System.Collections.Generic.Dictionary[string, string]]::new(
                    [System.StringComparer]::OrdinalIgnoreCase)
            foreach ($segment in $line.Split(';')) {
                $separator = $segment.IndexOf('=')
                if ($separator -le 0) {
                    continue
                }
                $fieldName = $segment.Substring(0, $separator).Trim()
                $lastSpace = $fieldName.LastIndexOf(' ')
                if ($lastSpace -ge 0) {
                    $fieldName = $fieldName.Substring($lastSpace + 1)
                }
                if ($fieldName -notmatch '^[a-zA-Z][a-zA-Z0-9_]*$') {
                    continue
                }
                if (-not $fields.ContainsKey($fieldName)) {
                    $fields.Add(
                        $fieldName,
                        $segment.Substring($separator + 1).Trim())
                }
            }

            $writerId = ''
            $writerSequence = ''
            [void]$fields.TryGetValue('log_writer_id', [ref]$writerId)
            [void]$fields.TryGetValue('log_writer_sequence', [ref]$writerSequence)
            if (-not [string]::IsNullOrWhiteSpace($writerId) -and
                -not [string]::IsNullOrWhiteSpace($writerSequence)) {
                $writerIdentity = '{0}|{1}' -f $writerId, $writerSequence
                if (-not $seenWriterRecords.Add($writerIdentity)) {
                    continue
                }
            }

            $eventName = ''
            [void]$fields.TryGetValue('event', [ref]$eventName)
            if ([string]::IsNullOrWhiteSpace($eventName)) {
                $eventMatch = [regex]::Match(
                    $line,
                    '(?i)(?:^|;\s*|\s)event=([^;\r\n\s]+)')
                if (-not $eventMatch.Success) {
                    continue
                }
                $eventName = $eventMatch.Groups[1].Value.Trim()
            }
            if ($null -ne $Metrics) {
                $Metrics.parsedRecordCount =
                    [long]$Metrics.parsedRecordCount + 1L
            }
            if (-not $relevantEvents.Contains($eventName)) {
                continue
            }
            $authority = ''
            $installGeneration = ''
            $repairKey = ''
            [void]$fields.TryGetValue('authority_id', [ref]$authority)
            [void]$fields.TryGetValue(
                'install_generation',
                [ref]$installGeneration)
            [void]$fields.TryGetValue('repair_request_key', [ref]$repairKey)
            $record = [pscustomobject]@{
                Index = $i
                Line = $line
                Fields = $fields
                Event = $eventName
                Authority = $authority
                InstallGeneration = $installGeneration
                RepairKey = $repairKey
            }
            Add-TunaGuiSettlementIndexRecord `
                -Index $eventIndex `
                -Key $eventName `
                -Record $record

            foreach ($identity in @(
                    @($authority, $installGeneration, $repairKey),
                    @($authority, $installGeneration, ''),
                    @($authority, '', $repairKey),
                    @('', $installGeneration, $repairKey),
                    @($authority, '', ''),
                    @('', $installGeneration, ''),
                    @('', '', $repairKey))) {
                if (@($identity | Where-Object {
                            -not [string]::IsNullOrWhiteSpace([string]$_)
                        }).Count -eq 0) {
                    continue
                }
                Add-TunaGuiSettlementIndexRecord `
                    -Index $identityIndex `
                    -Key (Get-TunaGuiSettlementIdentityKey `
                        -Event $eventName `
                        -Authority ([string]$identity[0]) `
                        -InstallGeneration ([string]$identity[1]) `
                        -RepairKey ([string]$identity[2])) `
                    -Record $record
            }
        }

        function Get-TunaGuiSettlementIndexRecords {
            param(
                [Parameter(Mandatory = $true)][string[]]$Events,
                [AllowEmptyString()][string]$Authority = '',
                [AllowEmptyString()][string]$InstallGeneration = '',
                [AllowEmptyString()][string]$RepairKey = ''
            )

            $result = [System.Collections.Generic.List[object]]::new()
            foreach ($eventName in $Events) {
                if ($null -ne $Metrics) {
                    $Metrics.settlementLookupCount =
                        [long]$Metrics.settlementLookupCount + 1L
                }
                $bucket = $null
                $identitySpecified =
                    -not [string]::IsNullOrWhiteSpace($Authority) -or
                    -not [string]::IsNullOrWhiteSpace($InstallGeneration) -or
                    -not [string]::IsNullOrWhiteSpace($RepairKey)
                if ($identitySpecified) {
                    $identityKey = Get-TunaGuiSettlementIdentityKey `
                        -Event $eventName `
                        -Authority $Authority `
                        -InstallGeneration $InstallGeneration `
                        -RepairKey $RepairKey
                    [void]$identityIndex.TryGetValue($identityKey, [ref]$bucket)
                }
                else {
                    [void]$eventIndex.TryGetValue($eventName, [ref]$bucket)
                }
                if ($null -ne $bucket) {
                    $result.AddRange($bucket)
                }
            }
            return [object[]]$result.ToArray()
        }
        function Test-TunaGuiRegularV4SupersededScopeMatch {
            param(
                [Parameter(Mandatory = $true)][string]$SourceLine,
                [Parameter(Mandatory = $true)][string]$CandidateLine
            )
            foreach ($field in @(
                    'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
                    'live_route_epoch', 'runtime_generation', 'terminal_generation',
                    'leg_generation', 'transport_epoch', 'bridge_recovery_generation',
                    'bridge_decision_generation', 'route_publication_generation',
                    'route_commit_generation', 'target_transport')) {
                if (-not (Test-TunaGuiLogLineFieldMatch `
                        -SourceLine $SourceLine `
                        -CandidateLine $CandidateLine `
                        -FieldName $field)) {
                    return $false
                }
            }
            return $true
        }

        function Test-TunaGuiVisibleAuthorityMatch {
            param([string]$Actual, [string]$Expected)
            return [string]::IsNullOrWhiteSpace($Actual) -or
                $Actual -in @('[redacted]', 'redacted') -or
                [string]::Equals($Actual, $Expected, [System.StringComparison]::OrdinalIgnoreCase)
        }

        $acceptedSettlements = @(
            Get-TunaGuiSettlementIndexRecords `
                -Events @('filetransfer_regular_v4_frontier_repair_settlement_accepted') |
                Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_regular_v4_frontier_repair_settlement_accepted')
        })
        if ($acceptedSettlements.Count -eq 0) {
            return $false
        }

        foreach ($accepted in $acceptedSettlements) {
            $settlementOutcome = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'outcome'
            $normalizedSettlementOutcome = $settlementOutcome.Replace('_', '').ToLowerInvariant()
            if ($normalizedSettlementOutcome -eq 'superseded') {
                $predecessorAuthority = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'authority_id'
                $successorAuthority = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'successor_authority_id'
                $successorInstallGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $accepted.Line `
                    -Name 'successor_install_generation'
                if ([string]::IsNullOrWhiteSpace($predecessorAuthority) -or
                    [string]::IsNullOrWhiteSpace($successorAuthority) -or
                    [string]::IsNullOrWhiteSpace($successorInstallGeneration)) {
                    return $false
                }

                $successorBinding = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_committed') `
                        -Authority $successorAuthority `
                        -InstallGeneration $successorInstallGeneration |
                        Where-Object {
                    $_.Index -lt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_committed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $successorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'predecessor_authority_id') -eq
                        $predecessorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $successorInstallGeneration -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -Last 1)
                if ($successorBinding.Count -eq 0) {
                    return $false
                }

                $repairKey = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'repair_request_key'
                $predecessorBinding = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_committed') `
                        -Authority $predecessorAuthority `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -lt $successorBinding[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_committed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq
                        $predecessorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -Last 1)
                if ($predecessorBinding.Count -eq 0) {
                    return $false
                }
                $predecessorInstallGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $predecessorBinding[0].Line `
                    -Name 'install_generation'

                $apply = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided') `
                        -InstallGeneration $successorInstallGeneration |
                        Where-Object {
                    $_.Index -gt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $successorInstallGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome') -eq 'Superseded' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status') -in @('applied', 'idempotent') -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '0' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared') -eq '1' -and
                    (Test-TunaGuiVisibleAuthorityMatch `
                        -Actual (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_id') `
                        -Expected $successorAuthority) -and
                    (Test-TunaGuiVisibleAuthorityMatch `
                        -Actual (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_authority_id') `
                        -Expected $predecessorAuthority) -and
                    (Test-TunaGuiVisibleAuthorityMatch `
                        -Actual (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'successor_authority_id') `
                        -Expected $successorAuthority) -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction')
                } | Group-Object {
                    [string]::Join('|', @(
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared'))).
                        ToLowerInvariant()
                } | ForEach-Object {
                    @($_.Group | Sort-Object Index)[0]
                } | Sort-Object Index)
                if ($apply.Count -ne 1) {
                    return $false
                }

                $bindingRetired = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_retired') `
                        -Authority $predecessorAuthority `
                        -InstallGeneration $predecessorInstallGeneration `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -gt $apply[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_retired')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq
                        $predecessorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $predecessorInstallGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_boundary') -eq 'settlement' -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
                if ($bindingRetired.Count -eq 0) {
                    return $false
                }

                $contractSettled = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_contract_settled') `
                        -Authority $predecessorAuthority `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -gt $bindingRetired[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_contract_settled')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq
                        $predecessorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'successor_authority_id') -eq
                        $successorAuthority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome') -eq 'Superseded'
                } | Select-Object -First 1)
                if ($contractSettled.Count -eq 0) {
                    return $false
                }

                continue
            }

            if ($normalizedSettlementOutcome -in @(
                    'progressobserved',
                    'missingdispatch',
                    'settledstalled',
                    'stalerejected')) {
                $authority = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'authority_id'
                $installGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $accepted.Line `
                    -Name 'successor_install_generation'
                $repairKey = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'repair_request_key'
                if ([string]::IsNullOrWhiteSpace($authority) -or
                    $authority -in @('[redacted]', 'redacted') -or
                    [string]::IsNullOrWhiteSpace($installGeneration) -or
                    [string]::IsNullOrWhiteSpace($repairKey)) {
                    return $false
                }

                $binding = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_committed') `
                        -Authority $authority `
                        -InstallGeneration $installGeneration `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -lt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_committed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -Last 1)
                if ($binding.Count -eq 0) {
                    return $false
                }

                if ($normalizedSettlementOutcome -eq 'stalerejected') {
                    $prepared = @(
                        Get-TunaGuiSettlementIndexRecords `
                            -Events @('filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_prepared') `
                            -Authority $authority `
                            -InstallGeneration $installGeneration |
                            Where-Object {
                        $_.Index -lt $accepted.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_prepared')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                            $installGeneration -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'route') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'protocol_version') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'live_route_epoch') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'runtime_generation') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'terminal_generation') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'leg_generation') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_bridge_decision_generation') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'bridge_decision_generation')
                    } | Select-Object -Last 1)
                    $committed = @(
                        Get-TunaGuiSettlementIndexRecords `
                            -Events @('filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed') `
                            -Authority $authority `
                            -InstallGeneration $installGeneration |
                            Where-Object {
                        $_.Index -gt $accepted.Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                            $installGeneration -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').
                            Replace('_', '').ToLowerInvariant() -eq $normalizedSettlementOutcome -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status').
                            ToLowerInvariant() -in @('applied', 'idempotent') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '1' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared') -eq '0' -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'route') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'protocol_version') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'live_route_epoch') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'runtime_generation') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'terminal_generation') -and
                        (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'leg_generation') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_bridge_decision_generation') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'bridge_decision_generation')
                    } | Select-Object -First 1)
                    if ($prepared.Count -eq 1 -and $committed.Count -eq 1) {
                        $atomicApply = @(
                            Get-TunaGuiSettlementIndexRecords `
                                -Events @('filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided') `
                                -InstallGeneration $installGeneration |
                                Where-Object {
                            $_.Index -gt $accepted.Index -and
                            $_.Index -lt $committed[0].Index -and
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                                $installGeneration -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').
                                Replace('_', '').ToLowerInvariant() -eq $normalizedSettlementOutcome -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status').
                                ToLowerInvariant() -in @('applied', 'idempotent') -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '1' -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared') -eq '0' -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction')
                        })
                        $operationGeneration = Get-TunaGuiLogLineFieldValue `
                            -Line $committed[0].Line `
                            -Name 'recovery_operation_generation'
                        $leaseAuthority = Get-TunaGuiLogLineFieldValue `
                            -Line $committed[0].Line `
                            -Name 'recovery_liveness_lease_authority_id'
                        $leaseGeneration = Get-TunaGuiLogLineFieldValue `
                            -Line $committed[0].Line `
                            -Name 'recovery_liveness_lease_generation'
                        $operationIssued = @(
                            Get-TunaGuiSettlementIndexRecords `
                                -Events @('filetransfer_receive_recovery_operation_issued') |
                                Where-Object {
                            $_.Index -gt $committed[0].Index -and
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'filetransfer_receive_recovery_operation_issued')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq
                                $operationGeneration -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_authority_id') -eq
                                $leaseAuthority -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_generation') -eq
                                $leaseGeneration -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                            (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction')
                        } | Select-Object -First 1)
                        $contractSettled = @(
                            Get-TunaGuiSettlementIndexRecords `
                                -Events @('filetransfer_regular_v4_frontier_repair_contract_settled') `
                                -Authority $authority `
                                -RepairKey $repairKey |
                                Where-Object {
                            $_.Index -gt $committed[0].Index -and
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'filetransfer_regular_v4_frontier_repair_contract_settled')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq
                                $repairKey -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').
                                Replace('_', '').ToLowerInvariant() -eq $normalizedSettlementOutcome
                        } | Select-Object -First 1)
                        if ($atomicApply.Count -eq 1 -and
                            $operationIssued.Count -eq 1 -and
                            $contractSettled.Count -eq 1) {
                            if (-not $RequireRecoveryProof) {
                                continue
                            }

                            $operationAuthority = Get-TunaGuiLogLineFieldValue `
                                -Line $operationIssued[0].Line `
                                -Name 'receive_recovery_operation_authority_id'
                            $receipt = @(
                                Get-TunaGuiSettlementIndexRecords `
                                    -Events @('filetransfer_receive_recovery_operation_execution_receipt_applied') |
                                    Where-Object {
                                $_.Index -gt $operationIssued[0].Index -and
                                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                    'filetransfer_receive_recovery_operation_execution_receipt_applied')) -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq
                                    $operationAuthority -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq
                                    $operationGeneration -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_authority_id') -eq
                                    $leaseAuthority -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_generation') -eq
                                    $leaseGeneration -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'execution_outcome') -eq 'Completed' -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'session_id') -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'direction')
                            } | Select-Object -First 1)
                            $proof = @(
                                Get-TunaGuiSettlementIndexRecords `
                                    -Events @('filetransfer_receive_recovery_operation_proof_observed') |
                                    Where-Object {
                                $_.Index -gt $operationIssued[0].Index -and
                                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                    'filetransfer_receive_recovery_operation_proof_observed')) -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq
                                    $operationAuthority -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq
                                    $operationGeneration -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_authority_id') -eq
                                    $leaseAuthority -and
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_generation') -eq
                                    $leaseGeneration -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'session_id') -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                                (Test-TunaGuiLogLineFieldMatch -SourceLine $operationIssued[0].Line -CandidateLine $_.Line -FieldName 'direction')
                            } | Select-Object -First 1)
                            if ($receipt.Count -eq 1 -and $proof.Count -eq 1) {
                                $completionBoundary = [Math]::Max(
                                    [int]$receipt[0].Index,
                                    [int]$proof[0].Index)
                                $adopted = @(
                                    Get-TunaGuiSettlementIndexRecords `
                                        -Events @('filetransfer_receive_recovery_operation_closure_adopted') |
                                        Where-Object {
                                    $_.Index -gt $completionBoundary -and
                                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                        'filetransfer_receive_recovery_operation_closure_adopted')) -and
                                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_authority_id') -eq
                                        $operationAuthority -and
                                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'receive_recovery_operation_generation') -eq
                                        $operationGeneration -and
                                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_authority_id') -eq
                                        $leaseAuthority -and
                                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'recovery_liveness_lease_generation') -eq
                                        $leaseGeneration -and
                                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'closure_state') -eq 'Adopted'
                                } | Select-Object -First 1)
                                if ($adopted.Count -eq 1) {
                                    continue
                                }
                            }
                        }
                    }

                    if ($RequireRecoveryProof) {
                        return $false
                    }
                }

                $retirement = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_retired') `
                        -Authority $authority `
                        -InstallGeneration $installGeneration `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -gt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_retired')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_boundary') -eq 'settlement' -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
                if ($retirement.Count -eq 0) {
                    return $false
                }

                $apply = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided') `
                        -InstallGeneration $installGeneration |
                        Where-Object {
                    $_.Index -gt $accepted.Index -and
                    $_.Index -lt $retirement[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').Replace('_', '').ToLowerInvariant() -eq
                        $normalizedSettlementOutcome -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status').ToLowerInvariant() -in
                        @('applied', 'idempotent') -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '1' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared') -eq '0' -and
                    (Test-TunaGuiVisibleAuthorityMatch `
                        -Actual (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') `
                        -Expected $authority) -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                    (Test-TunaGuiLogLineFieldMatch -SourceLine $accepted.Line -CandidateLine $_.Line -FieldName 'direction')
                } | Group-Object {
                    [string]::Join('|', @(
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'successor_authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared'))).
                        ToLowerInvariant()
                } | ForEach-Object {
                    @($_.Group | Sort-Object Index)[0]
                } | Sort-Object Index)
                if ($apply.Count -ne 1) {
                    return $false
                }

                if ($normalizedSettlementOutcome -eq 'stalerejected') {
                    # Without an atomic recovery-proof requirement, the exact
                    # coordinator apply plus binding retirement is terminal
                    # cleanup. Contract settlement is optional telemetry.
                    continue
                }

                $acceptedSuccessor = Get-TunaGuiLogLineFieldValue `
                    -Line $accepted.Line `
                    -Name 'successor_authority_id'
                $contractSettled = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_contract_settled') `
                        -Authority $authority `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -gt $retirement[0].Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_contract_settled')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'successor_authority_id') -eq
                        $acceptedSuccessor -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').Replace('_', '').ToLowerInvariant() -eq
                        $normalizedSettlementOutcome
                } | Group-Object {
                    [string]::Join('|', @(
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'successor_authority_id'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key'),
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome'))).
                        ToLowerInvariant()
                } | ForEach-Object {
                    @($_.Group | Sort-Object Index)[0]
                })
                if ($contractSettled.Count -ne 1) {
                    return $false
                }
                continue
            }

            if ($normalizedSettlementOutcome -in @('transferterminal', 'stalerejected')) {
                $authority = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'authority_id'
                $installGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $accepted.Line `
                    -Name 'successor_install_generation'
                $repairKey = Get-TunaGuiLogLineFieldValue -Line $accepted.Line -Name 'repair_request_key'
                if ([string]::IsNullOrWhiteSpace($authority) -or
                    $authority -in @('[redacted]', 'redacted') -or
                    [string]::IsNullOrWhiteSpace($installGeneration) -or
                    [string]::IsNullOrWhiteSpace($repairKey)) {
                    return $false
                }

                $binding = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_committed') `
                        -Authority $authority `
                        -InstallGeneration $installGeneration `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -lt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_committed')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -Last 1)
                if ($binding.Count -eq 0) {
                    return $false
                }

                $retirement = @(
                    Get-TunaGuiSettlementIndexRecords `
                        -Events @('filetransfer_regular_v4_frontier_repair_pressure_binding_retired') `
                        -Authority $authority `
                        -InstallGeneration $installGeneration `
                        -RepairKey $repairKey |
                        Where-Object {
                    $_.Index -gt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_pressure_binding_retired')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                        $installGeneration -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_boundary') -eq 'settlement' -and
                    (Test-TunaGuiRegularV4SupersededScopeMatch `
                        -SourceLine $accepted.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
                if ($retirement.Count -eq 1) {
                    $apply = @(
                        Get-TunaGuiSettlementIndexRecords `
                            -Events @('filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided') `
                            -InstallGeneration $installGeneration |
                            Where-Object {
                        $_.Index -gt $accepted.Index -and
                        $_.Index -lt $retirement[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq
                            $installGeneration -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').
                            Replace('_', '').ToLowerInvariant() -eq $normalizedSettlementOutcome -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status').
                            ToLowerInvariant() -in @('applied', 'idempotent') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '1' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared') -eq '0' -and
                        (Test-TunaGuiVisibleAuthorityMatch `
                            -Actual (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') `
                            -Expected $authority) -and
                        (Test-TunaGuiLogLineFieldMatch `
                            -SourceLine $accepted.Line `
                            -CandidateLine $_.Line `
                            -FieldName 'session_id') -and
                        (Test-TunaGuiLogLineFieldMatch `
                            -SourceLine $accepted.Line `
                            -CandidateLine $_.Line `
                            -FieldName 'transfer_id') -and
                        (Test-TunaGuiLogLineFieldMatch `
                            -SourceLine $accepted.Line `
                            -CandidateLine $_.Line `
                            -FieldName 'direction')
                    } | Group-Object {
                        [string]::Join('|', @(
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared'),
                                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'retained_predecessor_cleared'))).
                            ToLowerInvariant()
                    } | ForEach-Object {
                        @($_.Group | Sort-Object Index)[0]
                    })
                    if ($apply.Count -eq 1) {
                        # TransferTerminal and StaleRejected are diagnostic final
                        # outcomes. Exact apply plus binding retirement is the
                        # complete coordinator disposition; contract settlement
                        # is optional corroboration.
                        continue
                    }
                }

                return $false
            }

            $handoff = @(
                Get-TunaGuiSettlementIndexRecords `
                    -Events @(
                        'runtime_unlock_regular_v4_frontier_repair_settlement_released',
                        'runtime_unlock_regular_v4_frontier_repair_settlement_held',
                        'runtime_unlock_regular_v4_frontier_repair_settlement_rejected') |
                    Where-Object {
                $_.Index -gt $accepted.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'runtime_unlock_regular_v4_frontier_repair_settlement_released',
                    'runtime_unlock_regular_v4_frontier_repair_settlement_held',
                    'runtime_unlock_regular_v4_frontier_repair_settlement_rejected')) -and
                (Test-TunaGuiRegularV4FrontierRepairMatch -SourceLine $accepted.Line -CandidateLine $_.Line)
            })
            if ($handoff.Count -gt 0) {
                continue
            }

            $precontractClosure = @(
                foreach ($consumed in @(
                        Get-TunaGuiSettlementIndexRecords `
                            -Events @('runtime_unlock_regular_v4_frontier_repair_precontract_settlement_consumed') |
                            Where-Object {
                    $_.Index -gt $accepted.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_regular_v4_frontier_repair_precontract_settlement_consumed')) -and
                    (Test-TunaGuiRegularV4FrontierRepairMatch -SourceLine $accepted.Line -CandidateLine $_.Line)
                })) {
                    $closure = @(
                        Get-TunaGuiSettlementIndexRecords `
                            -Events @('regular_v4_receive_recovery_contract_closed_no_deferral') |
                            Where-Object {
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('regular_v4_receive_recovery_contract_closed_no_deferral')) -and
                        (Test-TunaGuiRegularV4FrontierRepairPrecontractClosureMatch -Accepted $accepted -Consumed $consumed -Closure $_)
                    })
                    if ($closure.Count -gt 0) {
                        $consumed
                    }
                }
            )
            if ($precontractClosure.Count -eq 0) {
                return $false
            }
        }

        return $true
    }

    function Test-TunaGuiRegularV4FrontierRepairStallUnresolved {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Lines
        )

        function Test-TunaGuiRegularV4FutureTailScopeMatch {
            param(
                [Parameter(Mandatory = $true)][string]$StallLine,
                [Parameter(Mandatory = $true)][string]$CandidateLine
            )

            foreach ($field in @('session_id', 'transfer_id', 'log_writer_id')) {
                $stallValue = Get-TunaGuiLogLineFieldValue -Line $StallLine -Name $field
                $candidateValue = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $field
                if ([string]::IsNullOrWhiteSpace($stallValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue) -or
                    -not [string]::Equals(
                        $stallValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            foreach ($field in @(
                    'direction', 'route', 'protocol_version', 'live_route_epoch',
                    'runtime_generation', 'terminal_generation', 'leg_generation',
                    'transport_epoch', 'bridge_recovery_generation',
                    'route_publication_generation', 'route_commit_generation')) {
                $stallValue = Get-TunaGuiLogLineFieldValue -Line $StallLine -Name $field
                $candidateValue = Get-TunaGuiLogLineFieldValue -Line $CandidateLine -Name $field
                if (-not [string]::IsNullOrWhiteSpace($stallValue) -and
                    -not [string]::IsNullOrWhiteSpace($candidateValue) -and
                    -not [string]::Equals(
                        $stallValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            return $true
        }

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $stalls = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'filetransfer_regular_v4_frontier_repair_stalled')
        })
        $seenStallScopes = [System.Collections.Generic.HashSet[string]]::new(
            [System.StringComparer]::Ordinal)
        foreach ($stall in $stalls) {
            $repairKey = Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'repair_request_key'
            if ([string]::IsNullOrWhiteSpace($repairKey)) {
                return $true
            }
            $stallScopeKey = (@(
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'session_id'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'transfer_id'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'direction'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'route'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'protocol_version'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'live_route_epoch'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'leg_generation'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'transport_epoch'
                    Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'bridge_recovery_generation'
                    $repairKey
                ) -join '|')
            if (-not $seenStallScopes.Add($stallScopeKey)) {
                continue
            }

            $progress = @($indexedLines | Where-Object {
                $_.Index -gt $stall.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_regular_v4_frontier_repair_progress_observed')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'direction') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'route') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'protocol_version') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'live_route_epoch') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'leg_generation') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'transport_epoch') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'bridge_recovery_generation')
            } | Select-Object -First 1)
            if ($progress.Count -eq 1) {
                continue
            }

            $tunaRecovery = $false
            $staleSettlement = @($indexedLines | Where-Object {
                    $_.Index -gt $stall.Index -and
                    (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                        'filetransfer_regular_v4_frontier_repair_settlement_accepted')) -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'outcome').Replace('_', '').ToLowerInvariant() -eq 'stalerejected' -and
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_reason') -eq
                        'tuna_activation_pause_tuna_activation_negotiating' -and
                    (Test-TunaGuiRegularV4FutureTailScopeMatch `
                        -StallLine $stall.Line `
                        -CandidateLine $_.Line)
                } | Select-Object -First 1)
            if ($staleSettlement.Count -eq 1) {
                $settlementAuthority = Get-TunaGuiLogLineFieldValue `
                    -Line $staleSettlement[0].Line -Name 'authority_id'
                $settlementInstall = Get-TunaGuiLogLineFieldValue `
                    -Line $staleSettlement[0].Line -Name 'successor_install_generation'
                $apply = @($indexedLines | Where-Object {
                        $_.Index -gt $staleSettlement[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'log_writer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'session_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'transfer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq $settlementInstall -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'settlement_outcome').Replace('_', '').ToLowerInvariant() -eq 'stalerejected' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'apply_status').ToLowerInvariant() -in @('applied', 'idempotent') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'current_authority_cleared') -eq '1'
                    } | Select-Object -First 1)
                $retired = @($indexedLines | Where-Object {
                        $apply.Count -eq 1 -and $_.Index -gt $apply[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_regular_v4_frontier_repair_pressure_binding_retired')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'log_writer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'authority_id') -eq $settlementAuthority -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_generation') -eq $settlementInstall -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'install_boundary') -eq 'settlement'
                    } | Select-Object -First 1)
                $commit = @($indexedLines | Where-Object {
                        $retired.Count -eq 1 -and $_.Index -gt $retired[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_route_transition_committed')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'log_writer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'session_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'transfer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'direction') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'direction') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transition_kind') -eq 'RegularV4ToTunaV4' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_route') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'route') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_live_route_epoch') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'live_route_epoch') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_runtime_generation') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $staleSettlement[0].Line -Name 'runtime_generation') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_leg_generation') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'leg_generation') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'source_route_publication_generation') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $staleSettlement[0].Line -Name 'route_publication_generation') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'target_route') -eq 'file_tuna_v4' -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'decision_status') -eq 'Committed'
                    } | Select-Object -First 1)
                $tunaProgress = @($indexedLines | Where-Object {
                        $commit.Count -eq 1 -and $_.Index -gt $commit[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                            'filetransfer_file_tuna_v4_frontier_repair_progress_observed')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'log_writer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'session_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'transfer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'live_route_epoch') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $commit[0].Line -Name 'target_live_route_epoch') -and
                        [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'committed_frontier_after') -gt
                            [int64](Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'committed_frontier_before')
                    } | Select-Object -First 1)
                $clear = @($indexedLines | Where-Object {
                        $tunaProgress.Count -eq 1 -and $_.Index -gt $tunaProgress[0].Index -and
                        (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_v4_repair_cleared')) -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'log_writer_id') -eq
                            (Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'log_writer_id') -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                        (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'reason') -eq 'frontier_advanced'
                    } | Select-Object -First 1)
                $tunaRecovery = $apply.Count -eq 1 -and $retired.Count -eq 1 -and
                    $commit.Count -eq 1 -and $tunaProgress.Count -eq 1 -and $clear.Count -eq 1
            }
            if ($tunaRecovery) {
                continue
            }

            $matchingSettlements = @($indexedLines | Where-Object {
                $_.Index -gt $stall.Index -and
                (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                    'filetransfer_regular_v4_frontier_repair_settlement_accepted')) -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq $repairKey -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'session_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'transfer_id') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'direction') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'route') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'protocol_version') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'live_route_epoch') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'leg_generation') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'transport_epoch') -and
                (Test-TunaGuiLogLineFieldMatch -SourceLine $stall.Line -CandidateLine $_.Line -FieldName 'bridge_recovery_generation')
            })
            $settlementResolved = $false
            foreach ($matchingSettlement in $matchingSettlements) {
                $authority = Get-TunaGuiLogLineFieldValue `
                    -Line $matchingSettlement.Line `
                    -Name 'authority_id'
                $installGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $matchingSettlement.Line `
                    -Name 'successor_install_generation'
                if ([string]::IsNullOrWhiteSpace($authority) -or
                    $authority -in @('[redacted]', 'redacted') -or
                    [string]::IsNullOrWhiteSpace($installGeneration) -or
                    $installGeneration -eq '0') {
                    continue
                }

                $settlementLines = @($indexedLines | Where-Object {
                    $candidate = $_
                    if ((Test-TunaGuiLogLineHasEvent -Line $candidate.Line -Events @(
                                'filetransfer_regular_v4_frontier_repair_settlement_accepted')) -and
                        $candidate.Index -ne $matchingSettlement.Index) {
                        return $false
                    }
                    foreach ($field in @(
                            'session_id',
                            'transfer_id',
                            'direction',
                            'route',
                            'protocol_version',
                            'live_route_epoch',
                            'leg_generation',
                            'transport_epoch',
                            'bridge_recovery_generation')) {
                        $anchorValue = Get-TunaGuiLogLineFieldValue -Line $matchingSettlement.Line -Name $field
                        $candidateValue = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name $field
                        if (-not [string]::IsNullOrWhiteSpace($anchorValue) -and
                            -not [string]::IsNullOrWhiteSpace($candidateValue) -and
                            $anchorValue -ne '(none)' -and
                            $candidateValue -ne '(none)' -and
                            $anchorValue -ne $candidateValue) {
                            return $false
                        }
                    }
                    $candidateAuthority = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'authority_id'
                    if (-not [string]::IsNullOrWhiteSpace($candidateAuthority) -and
                        $candidateAuthority -notin @('(none)', '[redacted]', 'redacted') -and
                        $candidateAuthority -ne $authority) {
                        return $false
                    }
                    $candidateInstallGeneration = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'install_generation'
                    if (-not [string]::IsNullOrWhiteSpace($candidateInstallGeneration) -and
                        $candidateInstallGeneration -ne '0' -and
                        $candidateInstallGeneration -ne $installGeneration) {
                        return $false
                    }
                    $candidateRepairKey = Get-TunaGuiLogLineFieldValue -Line $candidate.Line -Name 'repair_request_key'
                    return [string]::IsNullOrWhiteSpace($candidateRepairKey) -or
                        $candidateRepairKey -eq '(none)' -or
                        $candidateRepairKey -eq $repairKey
                } | ForEach-Object { $_.Line })
                $outcome = (Get-TunaGuiLogLineFieldValue `
                    -Line $matchingSettlement.Line `
                    -Name 'outcome').Replace('_', '').ToLowerInvariant()
                $startupFutureUnsent = $false
                [long]$frontier = -1
                [long]$requested = 0
                $frontierText = Get-TunaGuiLogLineFieldValue `
                    -Line $stall.Line `
                    -Name 'frontier_chunk_index'
                $requestedText = Get-TunaGuiLogLineFieldValue `
                    -Line $stall.Line `
                    -Name 'requested_chunk_count'
                if ((Get-TunaGuiLogLineFieldValue -Line $stall.Line -Name 'reason') -eq
                        'no_schedulable_repair_chunks' -and
                    [long]::TryParse($frontierText, [ref]$frontier) -and
                    [long]::TryParse($requestedText, [ref]$requested) -and
                    $frontier -ge 0 -and $requested -gt 0 -and
                    $frontier -le ([long]::MaxValue - $requested)) {
                    $grant = @($indexedLines | Where-Object {
                            $_.Index -lt $stall.Index -and
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'filetransfer_regular_v4_frontier_repair_authority_granted')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq
                                $repairKey -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'frontier_chunk_index') -eq
                                $frontierText -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_chunk_count') -eq
                                $requestedText -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'scheduled_chunk_count') -eq '0' -and
                            (Test-TunaGuiRegularV4FutureTailScopeMatch `
                                -StallLine $stall.Line `
                                -CandidateLine $_.Line)
                        } | Select-Object -Last 1)
                    $scheduled = @($indexedLines | Where-Object {
                            $_.Index -gt $stall.Index -and $_.Index -lt $matchingSettlement.Index -and
                            (Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                                'filetransfer_v4_repair_scheduled')) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'repair_request_key') -eq
                                $repairKey -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'first_start_chunk_index') -eq
                                $frontierText -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'last_end_chunk_exclusive') -eq
                                ([string]($frontier + $requested)) -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'requested_chunk_count') -eq
                                $requestedText -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'scheduled_chunk_count') -eq '0' -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'skipped_future_count') -eq
                                $requestedText -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'skipped_obsolete_count') -eq '0' -and
                            (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'skipped_out_of_bounds_count') -eq '0' -and
                            (Test-TunaGuiRegularV4FutureTailScopeMatch `
                                -StallLine $stall.Line `
                                -CandidateLine $_.Line)
                        })
                    if ($grant.Count -eq 1 -and $scheduled.Count -eq 1) {
                        $grantAuthority = Get-TunaGuiLogLineFieldValue `
                            -Line $grant[0].Line `
                            -Name 'authority_id'
                        $grantInstallGeneration = Get-TunaGuiLogLineFieldValue `
                            -Line $grant[0].Line `
                            -Name 'install_generation'
                        $startupFutureUnsent =
                            $grantAuthority -notin @('', '(none)', 'none', '[redacted]', 'redacted') -and
                            $grantInstallGeneration -match '^[1-9][0-9]*$' -and
                            $authority -eq $grantAuthority -and
                            $installGeneration -eq $grantInstallGeneration -and
                            (Get-TunaGuiLogLineFieldValue -Line $matchingSettlement.Line -Name 'settlement_reason') -eq
                                'tuna_activation_pause_tuna_activation_negotiating' -and
                            (Get-TunaGuiLogLineFieldValue -Line $matchingSettlement.Line -Name 'successor_authority_id') -in
                                @('', '(none)', 'none') -and
                            (Get-TunaGuiLogLineFieldValue -Line $matchingSettlement.Line -Name 'cleared_pressure') -eq '1' -and
                            (Test-TunaGuiRegularV4FutureTailScopeMatch `
                                -StallLine $stall.Line `
                                -CandidateLine $matchingSettlement.Line)
                    }
                }
                $settlementResolved = if ($outcome -eq 'stalerejected' -and -not $startupFutureUnsent) {
                    Test-TunaGuiRegularV4FrontierRepairSettlementClosed `
                        -Lines $settlementLines `
                        -RequireRecoveryProof
                }
                else {
                    Test-TunaGuiRegularV4FrontierRepairSettlementClosed -Lines $settlementLines
                }
                if ($settlementResolved) {
                    break
                }
            }
            if (-not $settlementResolved) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiRegularV4PredecessorSettlementClosedSuccessor {
        param([string[]]$Lines)

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $adoptions = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted')
        })
        $consumedEvents = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @(
                'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_consumed',
                'runtime_unlock_regular_v4_frontier_repair_precontract_settlement_consumed')
        })
        $lifecycleEvents = @($indexedLines | Where-Object {
            Test-TunaGuiLogLineHasEvent -Line $_.Line -Events @('filetransfer_regular_v4_recovery_liveness_bridge_lifecycle')
        })

        foreach ($consumed in $consumedEvents) {
            $sessionId = Get-TunaGuiLogLineFieldValue -Line $consumed.Line -Name 'session_id'
            $transferId = Get-TunaGuiLogLineFieldValue -Line $consumed.Line -Name 'transfer_id'
            $livenessGeneration = Get-TunaGuiLogLineFieldValue -Line $consumed.Line -Name 'adopted_recovery_liveness_generation'
            $bridgeDecisionGeneration = Get-TunaGuiLogLineFieldValue -Line $consumed.Line -Name 'adopted_bridge_decision_generation'
            if ([string]::IsNullOrWhiteSpace($livenessGeneration) -or $livenessGeneration -eq '0') {
                $adoption = @($adoptions | Where-Object {
                    $_.Index -lt $consumed.Index -and
                    (Test-TunaGuiRegularV4FrontierRepairMatch -SourceLine $consumed.Line -CandidateLine $_.Line)
                } | Select-Object -Last 1)
                if ($adoption.Count -gt 0) {
                    $livenessGeneration = Get-TunaGuiLogLineFieldValue -Line $adoption[0].Line -Name 'adopted_recovery_liveness_generation'
                    $bridgeDecisionGeneration = Get-TunaGuiLogLineFieldValue -Line $adoption[0].Line -Name 'adopted_bridge_decision_generation'
                }
            }

            $boundary = @($lifecycleEvents | Where-Object {
                $_.Index -lt $consumed.Index -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'session_id') -eq $sessionId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'transfer_id') -eq $transferId -and
                (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'lifecycle') -in @('completed', 'exhausted', 'receive_resumed') -and
                ([string]::IsNullOrWhiteSpace($livenessGeneration) -or $livenessGeneration -eq '0' -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'generation') -eq $livenessGeneration) -and
                ([string]::IsNullOrWhiteSpace($bridgeDecisionGeneration) -or $bridgeDecisionGeneration -eq '0' -or
                    (Get-TunaGuiLogLineFieldValue -Line $_.Line -Name 'bridge_decision_generation') -eq $bridgeDecisionGeneration)
            })
            if ($boundary.Count -eq 0) {
                return $true
            }
        }

        return $false
    }

    function Test-TunaGuiRouteTransitionDrainingTransportGraceFailure {
        param([string[]]$Lines)

        $indexedLines = @(
            for ($index = 0; $index -lt $Lines.Count; $index++) {
                [pscustomobject]@{ Index = $index; Line = [string]$Lines[$index] }
            }
        )
        $graceEvents = @($indexedLines | Where-Object {
            (Test-TunaGuiLogLineHasEvent `
                -Line $_.Line `
                -Events @('filetransfer_transport_grace_exhausted')) -and
            (Get-TunaGuiLogLineFieldValue `
                -Line $_.Line `
                -Name 'reason') -eq
                'filetransfer_route_transition_draining'
        })
        foreach ($grace in $graceEvents) {
            $writer = Get-TunaGuiLogLineFieldValue `
                -Line $grace.Line `
                -Name 'log_writer_id'
            $session = Get-TunaGuiLogLineFieldValue `
                -Line $grace.Line `
                -Name 'session_id'
            $transfer = Get-TunaGuiLogLineFieldValue `
                -Line $grace.Line `
                -Name 'transfer_id'
            $direction = Get-TunaGuiLogLineFieldValue `
                -Line $grace.Line `
                -Name 'direction'
            if ([string]::IsNullOrWhiteSpace($writer) -or
                [string]::IsNullOrWhiteSpace($session) -or
                [string]::IsNullOrWhiteSpace($transfer) -or
                [string]::IsNullOrWhiteSpace($direction)) {
                continue
            }

            $preparedEvents = @($indexedLines | Where-Object {
                $_.Index -lt $grace.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_route_transition_prepared')) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Prepared',
                        'Idempotent') -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'log_writer_id') -eq $writer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'session_id') -eq $session -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'transfer_id') -eq $transfer -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'direction') -eq $direction
            })
            $preparedEvents = @($preparedEvents | Where-Object {
                $candidate = $_
                $candidateAuthority = Get-TunaGuiLogLineFieldValue `
                    -Line $candidate.Line `
                    -Name 'authority_id'
                $candidateGeneration = Get-TunaGuiLogLineFieldValue `
                    -Line $candidate.Line `
                    -Name 'transition_generation'
                if ([string]::IsNullOrWhiteSpace($candidateAuthority) -or
                    [string]::IsNullOrWhiteSpace($candidateGeneration)) {
                    return $false
                }
                $candidateOperationEvents = @($indexedLines | Where-Object {
                    $_.Index -gt $candidate.Index -and
                    $_.Index -lt $grace.Index -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'authority_id') -eq $candidateAuthority -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'transition_generation') -eq
                        $candidateGeneration
                })
                $candidatePause = @($candidateOperationEvents | Where-Object {
                    Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_route_transition_pause_bound')
                })
                $candidateDraining = @($candidateOperationEvents | Where-Object {
                    Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @('filetransfer_route_transition_draining')
                })
                $candidateTerminal = @($candidateOperationEvents | Where-Object {
                    Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @(
                            'filetransfer_route_transition_committed',
                            'filetransfer_route_transition_invalidated')
                })
                return $candidatePause.Count -gt 0 -and
                    $candidateDraining.Count -gt 0 -and
                    $candidateTerminal.Count -eq 0
            })
            if ($preparedEvents.Count -ne 1) {
                continue
            }

            $prepared = $preparedEvents[0]
            $authority = Get-TunaGuiLogLineFieldValue `
                -Line $prepared.Line `
                -Name 'authority_id'
            $generation = Get-TunaGuiLogLineFieldValue `
                -Line $prepared.Line `
                -Name 'transition_generation'
            if ([string]::IsNullOrWhiteSpace($authority) -or
                [string]::IsNullOrWhiteSpace($generation)) {
                continue
            }

            $sameOperation = {
                param($Candidate)
                if ((Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'authority_id') -eq $authority -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'transition_generation') -eq $generation -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'session_id') -eq $session -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'transfer_id') -eq $transfer -and
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $Candidate.Line `
                        -Name 'direction') -eq $direction
                ) {
                    foreach ($field in @(
                            'transition_kind',
                            'source_route',
                            'source_protocol_version',
                            'source_transport',
                            'source_live_route_epoch',
                            'source_runtime_generation',
                            'source_route_publication_generation',
                            'source_route_commit_generation',
                            'source_terminal_generation',
                            'source_leg_generation',
                            'source_transport_epoch',
                            'source_bridge_recovery_generation',
                            'target_route',
                            'target_protocol_version',
                            'target_transport')) {
                        if (-not (Test-TunaGuiLogLineFieldMatch `
                                -SourceLine $prepared.Line `
                                -CandidateLine $Candidate.Line `
                                -FieldName $field)) {
                            return $false
                        }
                    }
                    $preparedDataSession =
                        Get-TunaGuiLogLineFieldValue `
                            -Line $prepared.Line `
                            -Name 'source_data_session_generation'
                    $candidateDataSession =
                        Get-TunaGuiLogLineFieldValue `
                            -Line $Candidate.Line `
                            -Name 'source_data_session_generation'
                    if ([string]::IsNullOrWhiteSpace($candidateDataSession)) {
                        $candidateDataSession =
                            Get-TunaGuiLogLineFieldValue `
                                -Line $Candidate.Line `
                                -Name 'data_session_generation'
                    }
                    return -not [string]::IsNullOrWhiteSpace(
                            $preparedDataSession) -and
                        -not [string]::IsNullOrWhiteSpace(
                            $candidateDataSession) -and
                        $preparedDataSession -eq $candidateDataSession
                }
                return $false
            }
            $pause = @($indexedLines | Where-Object {
                $_.Index -gt $prepared.Index -and
                $_.Index -lt $grace.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_route_transition_pause_bound')) -and
                (& $sameOperation $_) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -in @(
                        'Installed',
                        'Applied',
                        'Idempotent')
            })
            $draining = @($indexedLines | Where-Object {
                $_.Index -gt $prepared.Index -and
                $_.Index -lt $grace.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_route_transition_draining')) -and
                (& $sameOperation $_) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -eq 'Draining'
            })
            if ($pause.Count -eq 0 -or $draining.Count -eq 0) {
                continue
            }

            $invalidations = @($indexedLines | Where-Object {
                $_.Index -gt $grace.Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @('filetransfer_route_transition_invalidated')) -and
                (& $sameOperation $_) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_status') -eq 'Invalidated' -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'decision_reason') -in @(
                        'outbound_transfer_terminal',
                        'inbound_transfer_terminal',
                        'terminal_state')
            })
            if ($invalidations.Count -ne 1) {
                continue
            }

            $dispositions = @($indexedLines | Where-Object {
                $_.Index -gt $invalidations[0].Index -and
                (Test-TunaGuiLogLineHasEvent `
                    -Line $_.Line `
                    -Events @(
                        'filetransfer_route_transition_disposition_applied')) -and
                (& $sameOperation $_) -and
                (Get-TunaGuiLogLineFieldValue `
                    -Line $_.Line `
                    -Name 'disposition').Replace(
                        '_',
                        '').ToLowerInvariant() -eq 'terminalinvalidated'
            })
            if ($dispositions.Count -eq 0) {
                continue
            }

            $terminal = @($indexedLines | Where-Object {
                if ($_.Index -le $grace.Index -or
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'log_writer_id') -ne $writer -or
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'session_id') -ne $session -or
                    (Get-TunaGuiLogLineFieldValue `
                        -Line $_.Line `
                        -Name 'transfer_id') -ne $transfer) {
                    return $false
                }
                $expectedTerminalEvent = if ($direction -eq 'outbound') {
                    'file_transfer_outbound_terminal'
                }
                else {
                    'file_transfer_inbound_terminal'
                }
                return (Test-TunaGuiLogLineHasEvent `
                        -Line $_.Line `
                        -Events @($expectedTerminalEvent)) -and
                    (
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'state') -eq 'Failed' -or
                        (Get-TunaGuiLogLineFieldValue `
                            -Line $_.Line `
                            -Name 'error_code') -notin @(
                                '',
                                '(none)',
                                'none')
                    )
            })
            if ($terminal.Count -gt 0) {
                return $true
            }
        }

        return $false
    }

